const PERMISSOES_POR_CHAVE = {};
PERMISSOES.forEach((p) => { PERMISSOES_POR_CHAVE[p.chave] = p; });

function permissoesPadraoDoNivel(nv) {
  const p = {};
  PERMISSOES.forEach((x) => { p[x.chave] = Number(nv) >= x.nivelPadrao; });
  return p;
}

// ───────── cor do cargo ─────────
// O Admin Master escolhe a cor de cada cargo e ela aparece em tudo que o cargo
// fizer ou falar (chat, efetivo, equipes, provas, ficha...). 'lgbt' = arco-íris.
function limpaCorCargo(v) {
  const s = String(v == null ? '' : v).trim().toLowerCase();
  if (!s) return '';
  if (s === 'lgbt' || s === 'arco-iris' || s === 'arcoiris' || s === 'rainbow') return 'lgbt';
  // aceita uma cor ou duas misturadas: "#ff0000" ou "#ff0000|#000000"
  const partes = s.split(/[|,;+ ]+/).map(corHexCargo).filter(Boolean);
  if (!partes.length) return '';
  if (partes.length === 1) return partes[0];
  return partes[0] + '|' + partes[1];
}

function corHexCargo(v) {
  const t = String(v == null ? '' : v).trim().toLowerCase();
  if (/^#[0-9a-f]{6}$/.test(t)) return t;
  if (/^#[0-9a-f]{3}$/.test(t)) return '#' + t.slice(1).split('').map((c) => c + c).join('');
  if (/^[0-9a-f]{6}$/.test(t)) return '#' + t;
  return '';
}

// Lista padrão: se o cargo não tem permissões gravadas, usa as do nível.
const CARGOS_PADRAO = [
  { nome: 'Admin Master', nivel: 100, master: true },
  { nome: 'Chefe de Polícia', nivel: 90 },
  { nome: 'Delegado', nivel: 80 },
  { nome: 'Escrivão', nivel: 70 },
  { nome: 'Tático', nivel: 60 },
  { nome: 'Agente', nivel: 50 },
  { nome: 'Guarda Municipal', nivel: 40 },
  { nome: 'Civil', nivel: 10 },
].map((c) => ({ ...c, permissoes: permissoesPadraoDoNivel(c.nivel) }));

function listaCargos() {
  const salvos = (db && db.config && Array.isArray(db.config.cargos)) ? db.config.cargos : [];
  const base = salvos.length ? salvos : CARGOS_PADRAO;
  const vistos = new Set();
  const saida = [];
  base.forEach((c, i) => {
    const nome = String((c && c.nome) || '').trim();
    if (!nome || vistos.has(nome.toLowerCase())) return;
    vistos.add(nome.toLowerCase());
    const nv = Number(c && c.nivel);
    const nivelOk = Number.isFinite(nv) && nv > 0 ? Math.min(100, nv) : Math.max(10, 90 - i * 10);
    saida.push({
      nome,
      nivel: nivelOk,
      master: !!(c && c.master),
      cor: limpaCorCargo(c && c.cor),
      permissoes: { ...permissoesPadraoDoNivel(nivelOk), ...((c && c.permissoes) || {}) },
    });
  });
  return saida;
}

function cargoDe(nome) {
  return listaCargos().find((c) => c.nome === nome) || null;
}

function nivel(nome) {
  const c = cargoDe(nome);
  return c ? c.nivel : 0;
}

// Só o cargo marcado como dono (o primeiro, nível 100) manda nos cargos.
function ehMaster(u) {
  const c = cargoDe(u && u.cargo);
  return !!(c && c.master);
}

// Permissão do usuário: vem do cargo dele.
function pode(u, chave) {
  const c = cargoDe(u && u.cargo);
  if (!c) return false;
  if (c.master) return true;
  if (chave === 'cargos') return false;
  return (c.permissoes || {})[chave] === true;
}

function permissoesDe(u) {
  const c = cargoDe(u && u.cargo);
  if (!c) { const vazio = {}; PERMISSOES.forEach((p) => { vazio[p.chave] = false; }); return vazio; }
  if (c.master) { const tudo = {}; PERMISSOES.forEach((p) => { tudo[p.chave] = true; }); return tudo; }
  const p = { ...c.permissoes };
  p.cargos = false;
  return p;
}

// Mantém a lista coerente: dono no topo, níveis descendo conforme a ordem.
function normalizarCargos() {
  if (!db || !db.config || !Array.isArray(db.config.cargos) || !db.config.cargos.length) return;
  const arr = db.config.cargos;
  const iDono = arr.findIndex((c) => c && c.master);
  if (iDono > 0) arr.unshift(arr.splice(iDono, 1)[0]);
  if (!arr.some((c) => c && c.master) && arr[0]) arr[0].master = true;
  const total = arr.length;
  arr.forEach((c, i) => {
    if (!c || typeof c !== 'object') return;
    c.nome = String(c.nome || '').trim().slice(0, 30);
    c.master = !!c.master;
    c.cor = limpaCorCargo(c.cor);
    if (c.master) c.nivel = 100;
    else {
      // passo redondo: 10 em 10 até 10 cargos, depois 5 em 5, depois 2 em 2
      const passo = total <= 10 ? 10 : (total <= 19 ? 5 : 2);
      c.nivel = Math.max(2, 100 - i * passo);
    }
    const padrao = permissoesPadraoDoNivel(c.nivel);
    const atual = (c.permissoes && typeof c.permissoes === 'object') ? c.permissoes : {};
    const limpa = {};
    PERMISSOES.forEach((p) => { limpa[p.chave] = typeof atual[p.chave] === 'boolean' ? atual[p.chave] : padrao[p.chave]; });
    c.permissoes = limpa;
  });
  db.config.cargos = arr.filter((c) => c && c.nome);
}

