let db = {
  ...DB_VAZIO,
  config: { nomeSistema: NOME_PADRAO, nomeCorporacao: CORP_PADRAO, logo: null, tema: TEMA_PADRAO, regras: REGRAS_PADRAO },
};

function loadDB() {
  if (fs.existsSync(DB_FILE)) {
    try {
      db = { ...DB_VAZIO, ...JSON.parse(fs.readFileSync(DB_FILE, 'utf8')) };
    } catch (e) {
      console.error('data.json inválido, criando backup e reiniciando.', e.message);
      fs.renameSync(DB_FILE, DB_FILE + '.corrompido-' + Date.now());
    }
  }
}

function migrar() {
  if (!db.config) db.config = {};
  if (!Array.isArray(db.estudos)) db.estudos = [];
  if (!Array.isArray(db.estudosLidos)) db.estudosLidos = [];
  if (!db.config.regras || !String(db.config.regras).trim()) db.config.regras = REGRAS_PADRAO;
  if (!Array.isArray(db.config.codigosQ) || (!db.config.codigosQ.length && !db.config.codigosQEditado)) {
    db.config.codigosQ = CODIGOS_Q_PADRAO.map((c) => ({ ...c }));
  }
  // 'Agente Oficial' virou 'Agente'
  if (Array.isArray(db.users)) db.users.forEach((u) => { if (u.cargo === 'Agente Oficial') u.cargo = 'Agente'; });
  // cargos: nome, ordem e permissões (o Admin Master edita pelo sistema)
  if (!Array.isArray(db.config.cargos) || !db.config.cargos.length) {
    db.config.cargos = CARGOS_PADRAO.map((c) => ({ nome: c.nome, nivel: c.nivel, master: !!c.master, permissoes: { ...c.permissoes } }));
  }
  if (!db.config.cargos.some((c) => c && c.master)) {
    const dono = db.config.cargos.find((c) => /admin/i.test(String((c && c.nome) || '')));
    if (dono) dono.master = true;
    else db.config.cargos.unshift({ nome: 'Admin Master', nivel: 100, master: true, permissoes: permissoesPadraoDoNivel(100) });
  }
  if (!Array.isArray(db.chat)) db.chat = [];
  if (!Array.isArray(db.chatLideres)) db.chatLideres = [];
  if (!Array.isArray(db.solicitacoes)) db.solicitacoes = [];
  if (!Array.isArray(db.advertencias)) db.advertencias = [];
  if (!Array.isArray(db.cursos)) db.cursos = [];
  if (!Array.isArray(db.turnos)) db.turnos = [];
  if (!Array.isArray(db.push)) db.push = [];
  if (!Array.isArray(db.aprovacoes)) db.aprovacoes = [];
  if (!Array.isArray(db.equipes)) db.equipes = [];
  if (!Array.isArray(db.tickets)) db.tickets = [];
  if (!Array.isArray(db.ticketOpcoes)) db.ticketOpcoes = [];
  if (!db.ticketOpcoes.length && !(db.config && db.config.ticketOpcoesEditado)) {
    db.ticketOpcoes = [
      { nome: 'Dúvida', descricao: 'Perguntas sobre o RP, normas e procedimentos.' },
      { nome: 'Pedido ao comando', descricao: 'Pedidos, sugestões e assuntos do serviço.' },
      { nome: 'Problema no sistema', descricao: 'Algo travou, sumiu ou deu erro no sistema.' },
      { nome: 'Denúncia', descricao: 'Relatar a atitude de outro integrante.' },
      { nome: 'Outro assunto', descricao: 'Qualquer assunto que não esteja nas outras opções.' },
    ].map((o) => ({ id: uid(), nome: o.nome, descricao: o.descricao, criadoPor: 'Sistema', criadoEm: agora() }));
  }
  if (!db.config.codigoUnidade || !String(db.config.codigoUnidade).trim()) db.config.codigoUnidade = 'UNIDADE-01';
  if (!db.config.discord || typeof db.config.discord !== 'object') db.config.discord = { webhook: '', ligado: true };
  if (typeof db.config.discord.webhook !== 'string') db.config.discord.webhook = '';
  if (typeof db.config.discord.ligado !== 'boolean') db.config.discord.ligado = true;
  // bot do Discord: fica online na Discloud e entrega os avisos pelo token dele.
  // O sistema guarda SÓ o canal — o token do bot vive no config.json do bot.
  if (!db.config.discord.bot || typeof db.config.discord.bot !== 'object') db.config.discord.bot = { canal: '', ligado: true };
  if (typeof db.config.discord.bot.canal !== 'string') db.config.discord.bot.canal = '';
  if (typeof db.config.discord.bot.ligado !== 'boolean') db.config.discord.bot.ligado = true;
  if (typeof db.config.discord.bot.nome !== 'string') db.config.discord.bot.nome = '';
  if (typeof db.config.discord.bot.id !== 'string') db.config.discord.bot.id = '';
  if (typeof db.config.discord.bot.ultimoErro !== 'string') db.config.discord.bot.ultimoErro = '';
  if (!Number.isFinite(Number(db.config.discord.bot.ultimoContato))) db.config.discord.bot.ultimoContato = 0;
  if (!Number.isFinite(Number(db.config.discord.bot.entregas))) db.config.discord.bot.entregas = 0;
  delete db.config.discord.bot.token;    // versões antigas guardavam o token aqui: não fica mais
  delete db.config.discord.bot.codigo;   // nem o código do bot
  // canais separados no Discord: advertência (canal principal), promoção e rebaixamento
  if (!db.config.discord.bot.canais || typeof db.config.discord.bot.canais !== 'object') {
    db.config.discord.bot.canais = { promocao: '', rebaixamento: '' };
  }
  if (typeof db.config.discord.bot.canais.promocao !== 'string') db.config.discord.bot.canais.promocao = '';
  if (typeof db.config.discord.bot.canais.rebaixamento !== 'string') db.config.discord.bot.canais.rebaixamento = '';
  if (!db.config.discord.webhooks || typeof db.config.discord.webhooks !== 'object') {
    db.config.discord.webhooks = { promocao: '', rebaixamento: '' };
  }
  if (typeof db.config.discord.webhooks.promocao !== 'string') db.config.discord.webhooks.promocao = '';
  if (typeof db.config.discord.webhooks.rebaixamento !== 'string') db.config.discord.webhooks.rebaixamento = '';
  if (!Array.isArray(db.config.discord.botFila)) db.config.discord.botFila = [];
  normalizarCargos();
  // ninguém pode ficar com um cargo que não existe mais
  if (Array.isArray(db.users)) db.users.forEach((u) => {
    if (!db.config.cargos.some((c) => c.nome === u.cargo)) {
      db.config.cargos.push({ nome: String(u.cargo || 'Sem cargo').slice(0, 30), nivel: 10, master: false, permissoes: permissoesPadraoDoNivel(10) });
      normalizarCargos();
    }
  });
  if (typeof db.config.logo !== 'string') db.config.logo = null;
  if (!db.config.logoV) db.config.logoV = 1;
  if (!db.config.nomeSistema || !String(db.config.nomeSistema).trim() || db.config.nomeSistema === 'SIGP') db.config.nomeSistema = NOME_PADRAO;
  if (!db.config.nomeCorporacao || db.config.nomeCorporacao === 'Grupamento Municipal de Policiamento') db.config.nomeCorporacao = CORP_PADRAO;
  if (!['dourado', 'esmeralda', 'roxo', 'vermelho', 'azul'].includes(db.config.tema)) db.config.tema = TEMA_PADRAO;
  saveDBNow();
}

// Com DATABASE_URL (Postgres/Neon/Supabase) os dados ficam no banco e NÃO se
// perdem quando o Render reinicia. Sem ela, cai no arquivo data.json (como antes).
const TABELA = 'sigp_dados';
let pool = null;

function abrirBanco() {
  const url = process.env.DATABASE_URL;
  if (!url) return false;
  try {
    const { Pool } = require('pg');
    pool = new Pool({
      connectionString: url,
      ssl: /localhost|127\.0\.0\.1/.test(url) ? false : { rejectUnauthorized: false },
      max: 3,
    });
    if (typeof pool.on === 'function') pool.on('error', (e) => console.error('Banco (conexão ociosa):', e.message));
    return true;
  } catch (e) {
    console.error('DATABASE_URL definida, mas o pacote "pg" não está instalado:', e.message);
    pool = null;
    return false;
  }
}

async function carregarDoBanco() {
  if (!pool) return false;
  try {
    await pool.query(`CREATE TABLE IF NOT EXISTS ${TABELA} (id int PRIMARY KEY, dados jsonb NOT NULL, atualizado timestamptz DEFAULT now())`);
  } catch (e) {
    console.warn('Aviso ao criar a tabela (se ela já existir, está tudo certo):', e.message);
  }
  const r = await pool.query(`SELECT dados FROM ${TABELA} WHERE id = 1`);
  if (!r.rows.length) return false;
  const d = r.rows[0].dados;
  if (!d || typeof d !== 'object') return false;
  db = { ...DB_VAZIO, ...d };
  return true;
}

let bancoSalvando = false;
let bancoPendente = false;
function enviarAoBanco() {
  if (!pool) return;
  if (bancoSalvando) { bancoPendente = true; return; }
  bancoSalvando = true;
  const copia = JSON.stringify(db);
  pool.query(
    `INSERT INTO ${TABELA} (id, dados, atualizado) VALUES (1, $1::jsonb, now())
     ON CONFLICT (id) DO UPDATE SET dados = $1::jsonb, atualizado = now()`,
    [copia]
  ).catch((e) => console.error('Falha ao salvar no banco:', e.message))
   .finally(() => {
     bancoSalvando = false;
     if (bancoPendente) { bancoPendente = false; enviarAoBanco(); }
   });
}

function persistir() {
  try { fs.writeFileSync(DB_FILE, JSON.stringify(db, null, 2)); } catch (_) {}
  enviarAoBanco();
}

let saveTimer = null;
function saveDB() {
  clearTimeout(saveTimer);
  saveTimer = setTimeout(persistir, 40);
}
function saveDBNow() {
  clearTimeout(saveTimer);
  persistir();
}

// ───────── senhas ─────────
function hashSenha(senha) {
  const salt = crypto.randomBytes(16).toString('hex');
  const hash = crypto.scryptSync(String(senha), salt, 64).toString('hex');
  return salt + ':' + hash;
}
function checaSenha(senha, stored) {
  if (!stored || !stored.includes(':')) return false;
  const [salt, hash] = stored.split(':');
  const calc = crypto.scryptSync(String(senha), salt, 64).toString('hex');
  return crypto.timingSafeEqual(Buffer.from(hash, 'hex'), Buffer.from(calc, 'hex'));
}

const uid = () => crypto.randomBytes(8).toString('hex');
const agora = () => new Date().toISOString();
const horaBR = (iso) => new Date(iso).toLocaleString('pt-BR', { day: '2-digit', month: '2-digit', hour: '2-digit', minute: '2-digit' });

// ───────── ponto: tempo real trabalhado (descontando pausas) ─────────
const OFFSET_BR = -4; // horário de Campo Grande/MS (UTC-4)
const TURNOS_MS = OFFSET_BR * 3600 * 1000;

function pausasDe(reg) { return Array.isArray(reg && reg.pausas) ? reg.pausas : []; }

// milissegundos efetivamente trabalhados: (saída - entrada) - pausas
function msTrabalhados(reg) {
  if (!reg || !reg.entrada) return 0;
  const fim = reg.saida ? new Date(reg.saida).getTime() : Date.now();
  let ms = fim - new Date(reg.entrada).getTime();
  pausasDe(reg).forEach((p) => {
    const de = new Date(p.de).getTime();
    if (!Number.isFinite(de)) return;
    const ate = p.ate ? new Date(p.ate).getTime() : Date.now();
    ms -= Math.max(0, ate - de);
  });
  return Math.max(0, ms);
}
const minutosTrabalhados = (reg) => Math.round(msTrabalhados(reg) / 60000);

function msPausados(reg) {
  let ms = 0;
  pausasDe(reg).forEach((p) => {
    const de = new Date(p.de).getTime();
    if (!Number.isFinite(de)) return;
    const ate = p.ate ? new Date(p.ate).getTime() : Date.now();
    ms += Math.max(0, ate - de);
  });
  return ms;
}

// ───────── funcionário do mês (soma do ponto de todos no mês corrente) ─────────
function rankingPonto() {
  const ref = new Date(Date.now() + TURNOS_MS);
  const ano = ref.getUTCFullYear();
  const mes = ref.getUTCMonth();
  const mapa = new Map();
  db.ponto.forEach((p) => {
    if (!p.saida) return; // só conta ponto batido e finalizado
    const d = new Date(new Date(p.entrada).getTime() + TURNOS_MS);
    if (d.getUTCFullYear() !== ano || d.getUTCMonth() !== mes) return;
    const u = db.users.find((x) => x.id === p.userId);
    const atual = mapa.get(p.userId) || {
      userId: p.userId,
      nome: (u && u.nome) || p.nome || p.login || '—',
      login: (u && u.login) || p.login || '—',
      cargo: (u && u.cargo) || p.cargo || '—',
      minutos: 0,
      plantoes: 0,
      pausas: 0,
    };
    atual.minutos += Math.max(0, Number(p.minutos) || 0);
    atual.plantoes += 1;
    atual.pausas += pausasDe(p).length;
    mapa.set(p.userId, atual);
  });
  const lista = Array.from(mapa.values()).sort((a, b) => b.minutos - a.minutos || b.plantoes - a.plantoes);
  return {
    ano, mes: mes + 1,
    rotulo: ref.toLocaleDateString('pt-BR', { month: 'long', year: 'numeric', timeZone: 'UTC' }),
    lista: lista.slice(0, 30),
    total: lista.length,
    destaque: lista[0] || null,
  };
}

