const ADVERTENCIAS_ESPERANDO = [];

// ── fila de envio ──
// O Discord derruba (429) quando chegam muitos avisos juntos, e às vezes pede
// para esperar um tempo antes de tentar de novo. Aqui os envios saem em fila,
// um de cada vez, com um intervalo mínimo entre eles, e quando o Discord pede
// para esperar o sistema espera e tenta de novo sozinho.
const INTERVALO_MIN_DISCORD = 1300;   // ms entre dois envios (evita rajada)
const MAX_TENTATIVAS_DISCORD = 3;     // tentativas quando o Discord responde 429
const ESPERA_MAX_TENTATIVA = 8000;    // nunca segura a requisição mais que isso por tentativa
let ultimoEnvioDiscord = 0;
let filaDiscord = Promise.resolve();

function dormir(ms) { return new Promise((r) => setTimeout(r, ms)); }

// ── avisos que o Discord recusou por limite (429) ──
// Ficam guardados e saem sozinhos, um a um, quando o Discord liberar.
const MAX_PENDENTES_DISCORD = 25;
const VALIDADE_PENDENTE_MS = 24 * 60 * 60 * 1000;   // aviso velho (1 dia) é descartado

function pendentesDiscord() {
  if (!db.config.discord) db.config.discord = { webhook: '', ligado: true };
  if (!Array.isArray(db.config.discord.pendentes)) db.config.discord.pendentes = [];
  return db.config.discord.pendentes;
}

function guardarPendenteDiscord(payload, tipo) {
  try {
    const lista = pendentesDiscord();
    const texto = JSON.stringify(payload);
    if (lista.some((p) => p && p.corpo === texto)) return;   // não guarda o mesmo aviso duas vezes
    lista.push({ corpo: texto, tipo: tipo || '', em: Date.now() });
    while (lista.length > MAX_PENDENTES_DISCORD) lista.shift();
    saveDB();
  } catch (_) {}
}

function limparPendentesDiscord() {
  if (db.config && db.config.discord && Array.isArray(db.config.discord.pendentes) && db.config.discord.pendentes.length) {
    db.config.discord.pendentes = [];
    saveDB();
  }
}

function comFilaDiscord(tarefa) {
  const p = filaDiscord.then(async () => {
    const desde = Date.now() - ultimoEnvioDiscord;
    if (desde < INTERVALO_MIN_DISCORD) await dormir(INTERVALO_MIN_DISCORD - desde);
    try { return await tarefa(); } finally { ultimoEnvioDiscord = Date.now(); }
  });
  filaDiscord = p.then(() => {}, () => {});
  return p;
}

function postarDiscord(url, corpo) {
  return new Promise((resolve) => {
    const req = https.request({
      hostname: url.hostname,
      path: url.pathname + url.search,
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Content-Length': Buffer.byteLength(corpo),
        'User-Agent': 'SIGP (sistema policial RP, 1.1)',
      },
      timeout: 9000,
    }, (r) => {
      let txt = '';
      r.on('data', (c) => { txt += c; });
      r.on('end', () => {
        let dados = null;
        try { dados = txt ? JSON.parse(txt) : null; } catch (_) { dados = null; }
        const doCorpo = Number((dados && dados.retry_after) || 0);
        const doCabecalho = Number(r.headers && r.headers['retry-after']) || 0;
        const escopo = String((r.headers && r.headers['x-ratelimit-scope']) || '').toLowerCase();
        resolve({
          status: r.statusCode,
          dados: dados,
          escopo: escopo,
          global: escopo === 'global' || !!((dados && dados.global) || (r.headers && r.headers['x-ratelimit-global'] === 'true')),
          codigo: (dados && dados.code) || 0,
          espera: Math.max(0, doCorpo || doCabecalho || 0),   // segundos
        });
      });
    });
    req.on('timeout', () => { req.destroy(); resolve({ status: 0, rede: 'O Discord demorou para responder. Tente de novo.' }); });
    req.on('error', (e) => resolve({
      status: 0,
      rede: 'Não consegui falar com o Discord (' + ((e && e.message) || 'erro de rede') + '). O sistema continua normal e os avisos voltam quando a conexão melhorar.',
    }));
    req.write(corpo);
    req.end();
  });
}

function erroDoDiscord(r) {
  if (!r) return 'O Discord não respondeu. Tente de novo.';
  if (r.rede) return r.rede;
  if (r.status === 429) {
    const s = Math.max(1, Math.ceil(r.espera || 5));
    if (r.global) {
      return 'O Discord bloqueou o endereço do servidor (429 global) por ' + s + 's: não é o link nem o sistema, '
        + 'é o IP de onde os avisos saem que o Discord pôs de castigo. Insistir no botão só aumenta o castigo. '
        + 'Os avisos normais continuam na fila e saem sozinhos quando o Discord liberar.';
    }
    return 'O Discord limitou este canal (429): muitos avisos em pouco tempo. '
      + 'Espere cerca de ' + s + ' segundo' + (s > 1 ? 's' : '') + ' e toque em "Enviar aviso de teste" de novo. '
      + 'As advertências continuam sendo aplicadas normalmente, só o aviso no Discord fica para depois.';
  }
  if (r.status === 401 || r.status === 403) {
    return 'O Discord recusou o link (' + r.status + '). O webhook pode ter sido apagado no canal: crie outro e cole de novo.';
  }
  if (r.status === 404) {
    return 'O Discord respondeu 404: esse webhook não existe mais. Apague no Discord e crie um novo no canal.';
  }
  if (r.status === 400) {
    return 'O Discord recusou a mensagem (400). Confira se o link do webhook foi copiado inteiro, sem faltar pedaço.';
  }
  const detalhe = (r.dados && r.dados.message) ? ' (' + String(r.dados.message).slice(0, 120) + ')' : '';
  return 'O Discord respondeu ' + r.status + detalhe + '. Se continuar, apague o webhook no Discord e crie outro.';
}

// no plano B (webhook) cada canal tem o seu link: o de promoção e o de
// rebaixamento são opcionais e, sem eles, o aviso sai pelo link principal.
function webhookDoTipo(tipo) {
  const c = (db.config && db.config.discord) || {};
  const grupo = grupoDoTipo(tipo);
  const gu = (c.webhooks && typeof c.webhooks === 'object') ? c.webhooks : {};
  const proprio = String(gu[grupo] || '').trim();
  if (grupo !== 'adv' && proprio) return proprio;
  return String(c.webhook || '').trim();
}

async function enviarDiscord(payload, tipo) {
  const cfg = discordDoConfig();
  const alvoWebhook = webhookDoTipo(tipo);
  if (!alvoWebhook) return { ok: false, erro: 'Nenhum link de webhook do Discord configurado.' };
  if (!cfg.ligado) return { ok: false, erro: 'Os avisos no Discord estão desligados.' };
  if (!RE_WEBHOOK_DISCORD.test(alvoWebhook)) return { ok: false, erro: 'O link do webhook do Discord está inválido.' };
  let url;
  try { url = new URL(alvoWebhook); } catch (_) { return { ok: false, erro: 'Link do Discord inválido.' }; }

  // se o Discord já pediu uma pausa, espera acabar antes de tentar de novo
  const pausa = Number((db.config.discord && db.config.discord.esperarAte) || 0);
  if (pausa > Date.now()) {
    const faltam = Math.ceil((pausa - Date.now()) / 1000);
    const aviso = 'O Discord pediu uma pausa nos avisos (erro 429). Faltam ' + faltam + ' segundo' + (faltam > 1 ? 's' : '') + ' para poder enviar de novo. O aviso ficou guardado e sai sozinho.';
    if (tipo !== 'fila') guardarPendenteDiscord(payload, tipo);
    guardarResultadoDiscord({ ok: false, erro: aviso, status: 429 }, tipo);
    return { ok: false, erro: aviso, status: 429 };
  }

  const corpo = JSON.stringify(payload);
  const resultado = await comFilaDiscord(async () => {
    let ultimo = null;
    for (let tentativa = 1; tentativa <= MAX_TENTATIVAS_DISCORD; tentativa++) {
      const r = await postarDiscord(url, corpo);
      if (r.status >= 200 && r.status < 300) {
        if (db.config.discord) db.config.discord.esperarAte = 0;
        return { ok: true };
      }
      ultimo = r;
      if (r.status !== 429) break;                       // só o 429 vale nova tentativa
      if (r.global) break;                               // bloqueio do endereço (IP): insistir piora
      if (tentativa === MAX_TENTATIVAS_DISCORD) break;
      const espera = Math.min(ESPERA_MAX_TENTATIVA, Math.max(1200, Math.round((r.espera || 2) * 1000) + 300));
      await dormir(espera);
    }
    if (ultimo && ultimo.status === 429) {
      const s = Math.max(1, Math.ceil(ultimo.espera || 5));
      if (db.config.discord) db.config.discord.esperarAte = Date.now() + Math.min(s, 3600) * 1000;
    }
    if (ultimo && ultimo.status === 429 && tipo !== 'fila') guardarPendenteDiscord(payload, tipo);
    if (ultimo && (ultimo.status === 401 || ultimo.status === 403 || ultimo.status === 404)) limparPendentesDiscord();
    return {
      ok: false,
      erro: erroDoDiscord(ultimo),
      status: (ultimo && ultimo.status) || 0,
      global: !!(ultimo && ultimo.global),
      escopo: (ultimo && ultimo.escopo) || '',
      espera: (ultimo && ultimo.espera) || 0,
    };
  });

  guardarResultadoDiscord(resultado, tipo);
  return resultado;
}

// tenta mandar os avisos guardados (chamado sozinho a cada 20s)
let enviandoPendentesDiscord = false;
async function enviarPendentesDiscord() {
  if (enviandoPendentesDiscord) return;
  if (modoDeEntrega() === 'bot') return;   // com o bot ligado quem entrega é ele
  const cfg = discordDoConfig();
  if (!cfg.webhook || !cfg.ligado) return;
  const lista = pendentesDiscord();
  if (!lista.length) return;
  if (Number((db.config.discord && db.config.discord.esperarAte) || 0) > Date.now()) return;
  enviandoPendentesDiscord = true;
  try {
    while (lista.length) {
      const item = lista[0];
      if (!item || !item.corpo) { lista.shift(); continue; }
      if (Date.now() - Number(item.em || 0) > VALIDADE_PENDENTE_MS) { lista.shift(); saveDB(); continue; }
      let payload = null;
      try { payload = JSON.parse(item.corpo); } catch (_) { lista.shift(); saveDB(); continue; }
      const r = await enviarDiscord(payload, 'fila');
      if (r && r.ok) { lista.shift(); saveDB(); continue; }
      break;   // ainda recusado: tenta de novo na próxima rodada
    }
  } finally { enviandoPendentesDiscord = false; }
}

function totalAdvertencias(userId) {
  return (db.advertencias || []).filter((a) => a.userId === userId).length;
}

// manda a advertência para o canal do Discord (não trava o sistema se o Discord falhar)
// O cartão é montado aqui; o bot só repassa o embed pronto para o canal.
const ADV_BARRA = { leve: '▰▱▱', media: '▰▰▱', grave: '▰▰▰' };
function rodapeAviso(motivo) {
  const nome = textoAviso((db.config && db.config.nomeSistema) || 'Sistema', 60);
  return nome + ' · ' + (motivo || 'Registro disciplinar interno');
}

function advHoraCurta(v) {
  const d = new Date(v || Date.now());
  if (isNaN(d.getTime())) return '—';
  return d.toLocaleString('pt-BR', { timeZone: 'America/Campo_Grande', dateStyle: 'short', timeStyle: 'short' });
}

function cartaoAdvertencia(adv, o) {
  const g = GRAVIDADE_ADV[adv.gravidade] || GRAVIDADE_ADV.leve;
  const total = totalAdvertencias(adv.userId);

  const efetivo = '**' + textoAviso(adv.nome, 60) + '**'
    + (adv.login ? '\n`@' + textoAviso(adv.login, 40) + '`' : '');
  const cargo = textoAviso(adv.cargo, 40);
  const gravidade = g.emoji + ' **' + g.rotulo + '**\n' + (ADV_BARRA[adv.gravidade] || ADV_BARRA.leve);
  const quemAplicou = textoAviso(adv.aplicadaPor, 60) + (adv.aplicadaPorLogin ? '\n`@' + textoAviso(adv.aplicadaPorLogin, 40) + '`' : '');

  if (o.removida) {
    return {
      color: 0x2ecc71,
      title: '✅  Advertência retirada do registro',
      description: '> ' + textoAviso(adv.motivo, 380),
      fields: [
        { name: '👤 Efetivo', value: efetivo, inline: true },
        { name: '🎖️ Patente', value: cargo, inline: true },
        { name: '⚖️ Gravidade', value: gravidade, inline: true },
        { name: '📝 Justificativa da retirada', value: textoAviso(o.justificativa, 900), inline: false },
        { name: '📊 Advertências agora', value: '**' + total + '**', inline: true },
        { name: '🛡️ Retirada por', value: textoAviso(o.removidaPor, 60) + (o.removidaPorLogin ? '\n`@' + textoAviso(o.removidaPorLogin, 40) + '`' : ''), inline: true },
        { name: '🕒 Retirada em', value: advHoraCurta(o.removidaEm || Date.now()), inline: true },
      ],
      footer: { text: rodapeAviso() + ' · aplicada em ' + advHoraCurta(adv.em) },
      timestamp: new Date(o.removidaEm || Date.now()).toISOString(),
    };
  }

  return {
    color: g.cor,
    title: g.emoji + '  Advertência ' + g.rotulo.toLowerCase() + ' aplicada',
    description: '> ' + textoAviso(adv.motivo, 380),
    fields: [
      { name: '👤 Efetivo', value: efetivo, inline: true },
      { name: '🎖️ Patente', value: cargo, inline: true },
      { name: '⚖️ Gravidade', value: gravidade, inline: true },
      { name: '📊 Advertências acumuladas', value: '**' + total + '**', inline: true },
      { name: '🛡️ Aplicada por', value: quemAplicou, inline: true },
      { name: '🕒 Registro', value: advHoraCurta(adv.em), inline: true },
    ],
    footer: { text: rodapeAviso() },
    timestamp: new Date(adv.em || Date.now()).toISOString(),
  };
}

// manda um cartão pronto: pelo bot (fila, com o canal do tipo) ou pelo webhook
function enviarAvisoNoDiscord(payload, tipo, canal) {
  const modo = modoDeEntrega();
  if (!modo) return null;
  if (modo === 'bot') {
    const alvo = String(canal || canalDoBotPara(tipo) || '').trim();
    delete payload.username;                 // bot não troca de nome na mensagem
    enfileirarBot(payload, tipo, alvo);
    return { ok: true, naFila: true, canal: alvo };
  }
  const promessa = enviarDiscord(payload, tipo).catch(() => ({ ok: false }));
  ADVERTENCIAS_ESPERANDO.push(promessa);
  if (ADVERTENCIAS_ESPERANDO.length > 20) ADVERTENCIAS_ESPERANDO.shift();
  return promessa;
}

function avisarAdvertenciaNoDiscord(adv, opcoes) {
  if (!adv) return;
  const o = opcoes || {};
  const cartao = cartaoAdvertencia(adv, o);
  const base = String(process.env.RENDER_EXTERNAL_URL || '').replace(/\/+$/, '');
  if (base) cartao.thumbnail = { url: base + '/logo' };     // brasão no canto do cartão
  const payload = {
    username: textoAviso((db.config && db.config.nomeSistema) || 'POLÍCIA FEDERAL', 60),
    allowed_mentions: { parse: [] },
    embeds: [cartao],
  };
  const tipo = o.removida ? 'advertencia_removida' : 'advertencia';
  return enviarAvisoNoDiscord(payload, tipo);
}

// ── promoção e rebaixamento ──
// O cartão é montado aqui e entregue no canal do tipo: promoção vai para o
// canal de promoções, rebaixamento para o canal de rebaixamentos.
function cartaoCargo(d) {
  const promocao = d.tipo === 'promocao';
  const efetivo = '**' + textoAviso(d.nome, 60) + '**'
    + (d.login ? '\n`@' + textoAviso(d.login, 40) + '`' : '');
  const campos = [
    { name: '👤 Efetivo', value: efetivo, inline: true },
    { name: '🎖️ Patente anterior', value: textoAviso(d.de, 40), inline: true },
    { name: promocao ? '⬆️ Nova patente' : '⬇️ Nova patente', value: '**' + textoAviso(d.para, 40) + '**', inline: true },
    { name: promocao ? '🛡️ Promovido por' : '🛡️ Rebaixado por', value: textoAviso(d.por, 60) + (d.porLogin ? '\n`@' + textoAviso(d.porLogin, 40) + '`' : ''), inline: true },
    { name: '📊 Advertências', value: '**' + Number(d.advertencias || 0) + '**', inline: true },
    { name: '🕒 Registro', value: advHoraCurta(d.em || Date.now()), inline: true },
  ];
  if (d.motivo) campos.splice(3, 0, { name: '📝 Motivo', value: textoAviso(d.motivo, 400), inline: false });
  return {
    color: promocao ? 0x2ecc71 : 0xe74c3c,
    title: promocao ? '🎖️  Promoção' : '⬇️  Rebaixamento',
    description: promocao
      ? '> Parabéns, **' + textoAviso(d.nome, 60) + '**! Você subiu de **' + textoAviso(d.de, 40) + '** para **' + textoAviso(d.para, 40) + '**.'
      : '> **' + textoAviso(d.nome, 60) + '** foi rebaixado de **' + textoAviso(d.de, 40) + '** para **' + textoAviso(d.para, 40) + '**.',
    fields: campos,
    footer: { text: rodapeAviso(promocao ? 'Registro de promoções' : 'Registro de rebaixamentos') },
    timestamp: new Date(d.em || Date.now()).toISOString(),
  };
}

function avisarCargoNoDiscord(d) {
  if (!d || !d.tipo) return null;
  if (!modoDeEntrega()) return null;
  const cartao = cartaoCargo(d);
  const base = String(process.env.RENDER_EXTERNAL_URL || '').replace(/\/+$/, '');
  if (base) cartao.thumbnail = { url: base + '/logo' };
  const payload = {
    username: textoAviso((db.config && db.config.nomeSistema) || 'POLÍCIA FEDERAL', 60),
    allowed_mentions: { parse: [] },
    embeds: [cartao],
  };
  return enviarAvisoNoDiscord(payload, d.tipo);
}

// ───────── bot do Discord (fica 24h online na Discloud) ─────────
// O webhook vinha tomando 429 (o Discord bloqueia o endereço de saída do Render).
// O bot resolve isso: ele fica ligado na Discloud e manda no canal pelo próprio
// token, saindo do endereço dele. Aqui no sistema fica só o ID do canal; o token
// do bot vive no config.json do bot. O sistema confere o token no próprio Discord
// (e guarda a resposta por 15 minutos) para ninguém de fora ler a fila de avisos.
const RE_TOKEN_BOT = /^[A-Za-z0-9_\-]{20,}\.[A-Za-z0-9_\-]{5,}\.[A-Za-z0-9_\-]{20,}$/;
const MAX_FILA_BOT = 200;
const VALIDADE_FILA_BOT = 3 * 24 * 60 * 60 * 1000;   // aviso com mais de 3 dias é descartado
const BOT_ONLINE_MS = 120000;                         // falou com o sistema nos últimos 2 minutos
const BOT_HEARTBEAT_MS = 45000;                       // grava "estou vivo" no máximo a cada 45s
const TOKENS_BOT_OK = new Map();

function botDoConfig() {
  const d = (db.config && db.config.discord) || {};
  const b = (d.bot && typeof d.bot === 'object') ? d.bot : {};
  return {
    canal: String(b.canal || '').trim(),
    canais: {
      promocao: String((b.canais && b.canais.promocao) || '').trim(),
      rebaixamento: String((b.canais && b.canais.rebaixamento) || '').trim(),
    },
    ligado: b.ligado !== false,
    nome: String(b.nome || ''),
    id: String(b.id || ''),
    ultimoContato: Number(b.ultimoContato || 0),
    entregas: Number(b.entregas || 0),
    ultimoErro: String(b.ultimoErro || ''),
  };
}

// ── cada tipo de aviso tem o seu canal no Discord ──
// advertência no canal de advertências, promoção no de promoções e
// rebaixamento no de rebaixamentos. Se o canal próprio ainda não foi
// conectado, o aviso cai no canal de advertências para não se perder.
function grupoDoTipo(tipo) {
  const t = String(tipo || '').toLowerCase();
  if (t.indexOf('promocao') === 0) return 'promocao';
  if (t.indexOf('rebaixamento') === 0) return 'rebaixamento';
  return 'adv';
}
function nomeDoGrupo(grupo) {
  if (grupo === 'promocao') return 'promoções';
  if (grupo === 'rebaixamento') return 'rebaixamentos';
  return 'advertências';
}
function canalDoBotPara(tipo) {
  const b = botDoConfig();
  const grupo = grupoDoTipo(tipo);
  if (grupo === 'promocao' && b.canais.promocao) return b.canais.promocao;
  if (grupo === 'rebaixamento' && b.canais.rebaixamento) return b.canais.rebaixamento;
  return b.canal;
}

function botLigadoNoCanal() {
  const b = botDoConfig();
  return !!(b.canal && b.ligado);
}

function estadoBot() {
  const b = botDoConfig();
  return {
    canal: b.canal,
    canais: b.canais,
    ligado: b.ligado,
    configurado: !!b.canal,
    nome: b.nome,
    online: b.ultimoContato > 0 && (Date.now() - b.ultimoContato) < BOT_ONLINE_MS,
    ultimoContato: b.ultimoContato || null,
    entregas: b.entregas,
    ultimoErro: b.ultimoErro,
    fila: filaBot().length,
    convite: b.id ? ('https://discord.com/oauth2/authorize?client_id=' + b.id + '&scope=bot&permissions=19456') : '',
  };
}

function filaBot() {
  if (!db.config.discord) db.config.discord = { webhook: '', ligado: true };
  if (!Array.isArray(db.config.discord.botFila)) db.config.discord.botFila = [];
  return db.config.discord.botFila;
}

// quem entrega os avisos agora: o bot (se estiver ligado no canal) ou o webhook
function modoDeEntrega() {
  if (botLigadoNoCanal()) return 'bot';
  const c = discordDoConfig();
  if (c.webhook && c.ligado) return 'webhook';
  return '';
}

function enfileirarBot(payload, tipo, canal) {
  try {
    const lista = filaBot();
    const texto = JSON.stringify(payload);
    const alvo = String(canal || canalDoBotPara(tipo) || '').trim();
    // o mesmo aviso não entra duas vezes (o teste pode repetir)
    if (!/^teste/.test(String(tipo || '')) && lista.some((i) => i && i.corpo === texto)) return;
    lista.push({ id: uid(), corpo: texto, tipo: tipo || '', canal: alvo, em: Date.now() });
    while (lista.length > MAX_FILA_BOT) lista.shift();
    saveDB();
  } catch (_) {}
}

function avisosParaBot() {
  const lista = filaBot();
  const agoraMs = Date.now();
  const velhos = lista.filter((i) => !i || !i.corpo || (agoraMs - Number(i.em || 0)) > VALIDADE_FILA_BOT);
  if (velhos.length) {
    db.config.discord.botFila = lista.filter((i) => !velhos.includes(i));
    saveDB();
  }
  return db.config.discord.botFila.map((i) => {
    let payload = {};
    try { payload = JSON.parse(i.corpo); } catch (_) { payload = {}; }
    return { id: i.id, tipo: i.tipo || '', canal: i.canal || canalDoBotPara(i.tipo), payload: payload };
  });
}

// o Discord é quem diz se o token do bot presta (o sistema nunca guarda o token)
const API_DISCORD = String(process.env.DISCORD_API || 'https://discord.com/api/v10').replace(/\/+$/, '');

function conferirTokenNoDiscord(token) {
  return new Promise((resolve) => {
    let alvo = null;
    try { alvo = new URL(API_DISCORD + '/users/@me'); } catch (_) { return resolve({ status: 0, dados: null }); }
    const lib = alvo.protocol === 'http:' ? require('http') : https;
    const req = lib.request({
      hostname: alvo.hostname,
      port: alvo.port || undefined,
      path: alvo.pathname,
      method: 'GET',
      headers: { Authorization: 'Bot ' + token, 'User-Agent': 'SIGP (sistema policial RP, 1.1)' },
      timeout: 8000,
    }, (r) => {
      let txt = '';
      r.on('data', (c) => { txt += c; });
      r.on('end', () => {
        let dados = null;
        try { dados = txt ? JSON.parse(txt) : null; } catch (_) { dados = null; }
        resolve({ status: r.statusCode, dados: dados });
      });
    });
    req.on('timeout', () => { req.destroy(); resolve({ status: 0, dados: null }); });
    req.on('error', () => resolve({ status: 0, dados: null }));
    req.end();
  });
}

// o bot manda o token no cabeçalho x-bot-token; aqui a gente confere
async function botAutorizado(req) {
  const bruto = String((req.headers && (req.headers['x-bot-token'] || req.headers['authorization'])) || '')
    .replace(/^Bot\s+/i, '').trim();
  if (!RE_TOKEN_BOT.test(bruto)) return false;
  const visto = TOKENS_BOT_OK.get(bruto);
  if (visto && (Date.now() - visto) < 15 * 60 * 1000) return true;
  const r = await conferirTokenNoDiscord(bruto);
  if (r.status === 200 && r.dados && r.dados.id) {
    TOKENS_BOT_OK.set(bruto, Date.now());
    if (TOKENS_BOT_OK.size > 20) TOKENS_BOT_OK.clear();
    if (db.config.discord && db.config.discord.bot) {
      const nome = r.dados.discriminator && r.dados.discriminator !== '0'
        ? r.dados.username + '#' + r.dados.discriminator
        : String(r.dados.username || '');
      if (db.config.discord.bot.id !== String(r.dados.id)) db.config.discord.bot.id = String(r.dados.id);
      if (nome && db.config.discord.bot.nome !== nome) db.config.discord.bot.nome = nome;
      saveDB();
    }
    return true;
  }
  if (r.status === 401) { TOKENS_BOT_OK.delete(bruto); return false; }
  // Discord fora do ar ou pedindo calma: deixa o bot trabalhar (ele já provou saber o token)
  return true;
}

function botMarcarContato() {
  if (!db.config.discord || !db.config.discord.bot) return;
  const b = db.config.discord.bot;
  if (Date.now() - Number(b.ultimoContato || 0) < BOT_HEARTBEAT_MS) return;
  b.ultimoContato = Date.now();
  saveDB();
}

function botEntregues(entregues, permanentes, erro) {
  const ok = (Array.isArray(entregues) ? entregues : []).map(String);
  const naoDa = (Array.isArray(permanentes) ? permanentes : []).map(String);
  const lista = filaBot();
  const restante = lista.filter((i) => i && !ok.includes(String(i.id)) && !naoDa.includes(String(i.id)));
  let mudou = false;
  if (restante.length !== lista.length) {
    db.config.discord.botFila = restante;
    db.config.discord.bot.entregas = Number(db.config.discord.bot.entregas || 0) + ok.length;
    db.config.discord.bot.ultimoContato = Date.now();
    mudou = true;
  }
  if (erro) { db.config.discord.bot.ultimoErro = String(erro).slice(0, 300); mudou = true; }
  else if (ok.length && db.config.discord.bot.ultimoErro) { db.config.discord.bot.ultimoErro = ''; mudou = true; }
  if (mudou) saveDB();
}

// ───────── utilidades http ─────────
function json(res, code, obj) {
  const body = JSON.stringify(obj);
  res.writeHead(code, {
    'Content-Type': 'application/json; charset=utf-8',
    'Content-Length': Buffer.byteLength(body),
    'Access-Control-Allow-Origin': '*',
  });
  res.end(body);
}
function lerCorpo(req) {
  return new Promise((resolve, reject) => {
    let raw = '';
    req.on('data', (c) => {
      raw += c;
      if (raw.length > 8 * 1024 * 1024) { reject(new Error('Corpo muito grande')); req.destroy(); }
    });
    req.on('end', () => {
      if (!raw) return resolve({});
      try { resolve(JSON.parse(raw)); } catch (e) { reject(new Error('JSON inválido')); }
    });
    req.on('error', reject);
  });
}
// foto em uso: a que o usuário escolheu ou, senão, o brasão gravado no arquivo
function logoEmUso() {
  const c = db.config || {};
  if (c.logoSemFoto === true) return null;
  return c.logo || LOGO_PADRAO || null;
}

// config que vai para o navegador (a foto fica em /logo, para não pesar)
function configPublico() {
  const c = db.config || {};
  return {
    nomeSistema: c.nomeSistema || NOME_PADRAO,
    nomeCorporacao: c.nomeCorporacao || CORP_PADRAO,
    tema: c.tema || TEMA_PADRAO,
    logoUrl: logoEmUso() ? '/logo?v=' + (c.logoV || 1) : null,
    logoV: c.logoV || 0,
    iconeV: c.iconeV || 0,
    iconeLogoV: c.iconeLogoV || 0,
    avisosCelular: webpush ? ((vapid() || {}).publicKey || null) : null,
  };
}

const publico = (u) => ({
  id: u.id, nome: u.nome, login: u.login, cargo: u.cargo, ativo: u.ativo,
  suspensoAte: u.suspensoAte, suspensaoMotivo: u.suspensaoMotivo, suspensaoPor: u.suspensaoPor,
  pontos: u.pontos || 0, foto: u.foto || null, recado: u.recado || '',
  criadoEm: u.criadoEm, ultimoAcesso: u.ultimoAcesso,
});

// ───────── aprovações: quem passou e quem reprovou ─────────
// Toda prova corrigida (automática, manual ou reprovação por antifraude) entra
// sozinha na fileira de aprovados ou de reprovados. O comando também pode
// registrar a decisão na mão e trocar de fileira quando quiser.
function registrarDecisaoProva(entrega, motivoManual) {
  if (!entrega || !entrega.provaId) return null;
  if (entrega.status !== 'Aprovada' && entrega.status !== 'Reprovada') return null;
  const aprovado = entrega.status === 'Aprovada';
  let reg = db.aprovacoes.find((a) => a.origem === 'prova' && a.userId === entrega.userId && a.provaId === entrega.provaId);
  if (!reg) {
    reg = { id: uid(), origem: 'prova', userId: entrega.userId, provaId: entrega.provaId, em: agora() };
    db.aprovacoes.unshift(reg);
  }
  reg.nome = entrega.nome || reg.nome || '—';
  reg.login = entrega.login || reg.login || '';
  reg.cargo = entrega.cargo || reg.cargo || '';
  reg.provaTitulo = entrega.provaTitulo || reg.provaTitulo || 'Prova';
  reg.decisao = aprovado ? 'Aprovado' : 'Reprovado';
  reg.percentual = entrega.percentual != null ? entrega.percentual : null;
  reg.motivo = String(motivoManual || (entrega.reprovadaAuto ? entrega.motivoReprovacao : '') || '').slice(0, 300);
  reg.por = entrega.avaliadoPor || 'automático';
  reg.em = agora();
  if (db.aprovacoes.length > 2000) db.aprovacoes.length = 2000;
  return reg;
}

// ───────── equipes: presença na base, Cias, viaturas e patrulhamento ─────────
// Formação no molde do script do BOPE: equipes de 2 a 4 integrantes, funções
// distribuídas por hierarquia e antiguidade (o mais antigo é P2, depois P1, P3
// e P4), nome na sequência NATO (Alfa, Bravo, Charlie...) e prioridade para
// encher uma equipe incompleta antes de abrir outra. Entrar na base e sair de
// serviço refazem a escalação na hora, sem ninguém ficar sozinho.
const CIAS = [
  { nome: '1ª Cia', cidade: 'Los Santos' },
  { nome: '2ª Cia', cidade: 'Las Venturas' },
  { nome: '3ª Cia', cidade: 'San Fierro' },
];
const TAMANHOS_EQUIPE = [2, 3, 4];   // capacidade que o Comando escolhe (2 a 4)
const MAX_VIATURAS = 3;
const LIMITE_EQUIPE = 4;             // capacidade máxima de uma equipe
const MINIMO_EQUIPE = 2;             // ninguém fica sozinho em serviço
const FUNCOES_EQUIPE = ['P2', 'P1', 'P3', 'P4'];  // ordem por hierarquia/antiguidade
const NOMES_EQUIPES = [
  'Alfa', 'Bravo', 'Charlie', 'Delta', 'Eco', 'Foxtrot', 'Golf', 'Hotel', 'India',
  'Juliett', 'Kilo', 'Lima', 'Mike', 'November', 'Oscar', 'Papa', 'Quebec', 'Romeo',
  'Sierra', 'Tango', 'Uniform', 'Victor', 'Whiskey', 'X-ray', 'Yankee', 'Zulu',
];
const AVISO_SOZINHO = 'aguarde mais um colega de equipe na base';
const AVISO_MANUAL = 'sem equipe na escalação manual — o Comando define quem entra';
const MODOS_FORMACAO = ['auto', 'manual'];

function hojeLocalISO() {
  return new Date(Date.now() + TURNOS_MS).toISOString().slice(0, 10);
}
function solicitacaoVigente(userId, tipos) {
  const hoje = hojeLocalISO();
  return (db.solicitacoes || []).find((s) => {
    if (s.userId !== userId || s.status !== 'aprovada') return false;
    if (!tipos.includes(s.tipo)) return false;
    if (s.tipo === 'afastamento') return s.de <= hoje && (s.ate || s.de) >= hoje;
    return s.de === hoje;
  }) || null;
}
function pontoAbertoDe(userId) {
  return (db.ponto || []).find((p) => p.userId === userId && !p.saida) || null;
}
function estaPresente(u) {
  if (!u || !u.ativo) return false;
  if (u.suspensoAte && new Date(u.suspensoAte).getTime() > Date.now()) return false;
  if (!pontoAbertoDe(u.id)) return false;
  if (solicitacaoVigente(u.id, ['afastamento', 'folga'])) return false;
  return true;
}
// quem está na base: precisa ter batido o ponto e não estar de folga/afastado
function listaPresentes() {
  return db.users
    .filter(estaPresente)
    .map((u) => {
      const p = pontoAbertoDe(u.id);
      return { ...publico(u), entradaPonto: p.entrada, pontoId: p.id, desde: p.entrada };
    })
    .sort((a, b) => new Date(a.entradaPonto) - new Date(b.entradaPonto));
}
function listaAusentes() {
  const hoje = hojeLocalISO();
  return db.users.filter((u) => u.ativo).map((u) => {
    const s = solicitacaoVigente(u.id, ['justificativa']);
    return s ? { ...publico(u), motivo: s.motivo, de: s.de, tipo: s.tipo } : null;
  }).filter(Boolean);
}
function listaAfastados() {
  return db.users.filter((u) => u.ativo).map((u) => {
    const s = solicitacaoVigente(u.id, ['afastamento', 'folga']);
    return s ? { ...publico(u), solId: s.id, motivo: s.motivo, de: s.de, ate: s.ate, tipo: s.tipo, desde: s.de } : null;
  }).filter(Boolean);
}
// quando faltam viaturas, duas ou três Cias passam a ser cobertas juntas
function gruposCias(viaturas) {
  const grupos = CIAS.map((c) => [c]);
  const limite = Math.max(1, Math.min(CIAS.length, Number(viaturas) || 1));
  while (grupos.length > limite) {
    const primeiro = grupos.shift();
    grupos[0] = primeiro.concat(grupos[0]);
  }
  return grupos.map((lista) => ({
    nome: lista.map((c) => c.nome).join(' + '),
    cidades: lista.map((c) => c.cidade).join(' + '),
    unida: lista.length > 1,
    cis: lista.map((c) => c.nome),
  }));
}
// patente do policial: no SIGP a hierarquia é a ordem dos cargos (nível)
function patenteRank(u) {
  return nivel(u && u.cargo) || 0;
}
// antiguidade: data de cadastro. Quem não tem data entra depois de todo mundo.
function antiguidade(u) {
  const t = Date.parse(String((u && (u.criadoEm || u.created_date)) || ''));
  return Number.isFinite(t) ? t : Number.MAX_SAFE_INTEGER;
}
// escala as funções dentro da equipe: o mais antigo/patente alta vira P2,
// depois P1, P3 e P4 (ordem do script do BOPE).
function escalarFuncoes(membros) {
  return membros
    .slice()
    .sort((a, b) => {
      const pa = patenteRank(a);
      const pb = patenteRank(b);
      if (pa !== pb) return pb - pa;
      const aa = antiguidade(a);
      const ab = antiguidade(b);
      if (aa !== ab) return aa - ab;
      return String(a.id).localeCompare(String(b.id));
    })
    .map((m, i) => ({ ...m, posicao: FUNCOES_EQUIPE[i] || 'P' + (i + 1) }));
}
// divide o efetivo em equipes de 2 a 4: enche a equipe até a capacidade antes
// de abrir outra, nunca deixa ninguém sozinho e não passa das viaturas.
function dividirEquipes(total, capacidade, maxTimes) {
  const cap = Math.max(MINIMO_EQUIPE, Math.min(LIMITE_EQUIPE, Number(capacidade) || LIMITE_EQUIPE));
  const limite = Math.max(1, Number(maxTimes) || 1);
  const tamanhos = [];
  let restantes = Math.max(0, Math.floor(Number(total) || 0));
  while (restantes >= MINIMO_EQUIPE && tamanhos.length < limite) {
    let tam = Math.min(cap, restantes);
    if (restantes - tam === 1) tam -= 1; // o que sobra tem que dar um par
    if (tam < MINIMO_EQUIPE) break;
    tamanhos.push(tam);
    restantes -= tam;
  }
  return tamanhos;
}
// nome da equipe na sequência NATO: Alfa, Bravo, Charlie...
function nomeEquipe(indice) {
  return NOMES_EQUIPES[indice] || 'Equipe ' + String(indice + 1).padStart(2, '0');
}
function formacaoDaUnidade(codigo) {
  return (db.equipes || []).find((e) => e.unidade === codigo) || null;
}
function codigoUnidade() {
  return String((db.config && db.config.codigoUnidade) || 'UNIDADE-01').slice(0, 30);
}
// escalação manual: o Comando escolhe a equipe de cada policial na base.
// As funções continuam saindo da hierarquia (P2 mais antigo, depois P1, P3, P4).
function equipesManuais(saida, form, presentes) {
  const mapa = (form && form.manual && typeof form.manual === 'object') ? form.manual : {};
  const cap = Math.max(MINIMO_EQUIPE, Math.min(LIMITE_EQUIPE, Number(saida.tamanho) || LIMITE_EQUIPE));
  const fora = [];
  const porNome = new Map();
  presentes.forEach((p) => {
    const nome = NOMES_EQUIPES.includes(String(mapa[p.id] || '')) ? String(mapa[p.id]) : null;
    if (!nome) return;
    saida.escalacao[p.id] = nome;
    if (!porNome.has(nome)) porNome.set(nome, []);
    porNome.get(nome).push(p);
  });
  const naOrdem = NOMES_EQUIPES.filter((n) => porNome.has(n));
  naOrdem.forEach((nome, idx) => {
    const escalados = escalarFuncoes(porNome.get(nome));
    if (idx >= saida.viaturas) {
      escalados.forEach((p) => fora.push({ ...p, motivo: `equipe ${nome} não entrou: só ${saida.viaturas} viatura(s) disponível(is)` }));
      return;
    }
    const membros = escalados.slice(0, cap);
    escalados.slice(cap).forEach((p) => fora.push({ ...p, motivo: `equipe ${nome} está cheia (limite de ${cap} integrantes)` }));
    if (membros.length < MINIMO_EQUIPE) {
      membros.forEach((p) => fora.push({ ...p, motivo: `equipe ${nome} precisa de pelo menos ${MINIMO_EQUIPE} integrantes` }));
      return;
    }
    const grupo = saida.grupos[idx % saida.grupos.length];
    saida.equipes.push({
      numero: saida.equipes.length + 1,
      nome,
      local: 'Cia ' + grupo.nome,
      cia: grupo.nome,
      cidades: grupo.cidades,
      ciUnidas: grupo.unida,
      viatura: 'VTR-' + String(saida.equipes.length + 1).padStart(2, '0'),
      patrulhamento: true,
      membros,
      minima: membros.length <= MINIMO_EQUIPE,
    });
  });
  const emEquipe = new Set();
  saida.equipes.forEach((e) => e.membros.forEach((m) => emEquipe.add(m.id)));
  const foraIds = new Set(fora.map((p) => p.id));
  const semEquipe = presentes
    .filter((p) => !emEquipe.has(p.id) && !foraIds.has(p.id))
    .map((p) => ({ ...p, motivo: AVISO_MANUAL }));
  saida.semLocal = [...fora, ...semEquipe];
  saida.aviso = saida.equipes.length
    ? (saida.semLocal.length ? `Escalação manual: ${saida.semLocal.length} na base fora de equipe.` : '')
    : 'Escalação manual sem nenhuma equipe completa (mínimo 2 integrantes). Ajuste e salve de novo.';
  return saida;
}

// monta as equipes agora, com quem está na base neste instante
function calcularEquipesCru() {
  const codigo = codigoUnidade();
  const form = formacaoDaUnidade(codigo);
  const presentes = listaPresentes();
  const saida = {
    unidade: codigo,
    formada: false,
    tamanho: null,
    viaturas: 0,
    formadaPor: null,
    formadaEm: null,
    presentes,
    ausentes: listaAusentes(),
    afastados: listaAfastados(),
    equipes: [],
    semLocal: [],
    aviso: '',
    modo: 'auto',
    escalacao: {},
    cis: CIAS.map((c) => ({ nome: c.nome, cidade: c.cidade })),
    grupos: gruposCias(form && form.viaturas ? form.viaturas : 1),
  };
  if (!form || form.ativa === false) {
    saida.aviso = presentes.length
      ? 'Nenhuma equipe formada. O Comando precisa clicar em Formar equipe.'
      : 'Ninguém na base agora. Bata o ponto para entrar em serviço.';
    return saida;
  }
  const tamanho = TAMANHOS_EQUIPE.includes(Number(form.tamanho)) ? Number(form.tamanho) : LIMITE_EQUIPE;
  saida.formada = true;
  saida.tamanho = tamanho;
  saida.viaturas = Math.max(1, Math.min(MAX_VIATURAS, Number(form.viaturas) || 1));
  saida.formadaPor = form.formadaPor || null;
  saida.formadaEm = form.formadaEm || null;
  saida.grupos = gruposCias(saida.viaturas);
  saida.modo = MODOS_FORMACAO.includes(form.modo) ? form.modo : 'auto';
  if (saida.modo === 'manual') return equipesManuais(saida, form, presentes);

  // ordem: primeiro quem o Comando escalou, depois quem bateu o ponto mais cedo
  const ordem = Array.isArray(form.ordem) ? form.ordem : [];
  const fila = presentes.slice().sort((a, b) => {
    const ia = ordem.indexOf(a.id), ib = ordem.indexOf(b.id);
    if (ia >= 0 && ib >= 0) return ia - ib;
    if (ia >= 0) return -1;
    if (ib >= 0) return 1;
    return new Date(a.entradaPonto) - new Date(b.entradaPonto);
  });

  if (fila.length < 2) {
    saida.semLocal = fila.map((p) => ({ ...p, motivo: AVISO_SOZINHO }));
    saida.aviso = AVISO_SOZINHO;
    return saida;
  }

  const tamanhos = dividirEquipes(fila.length, tamanho, saida.viaturas);
  const grupos = saida.grupos;
  let cursor = 0;
  tamanhos.forEach((tam, idx) => {
    const membros = fila.slice(cursor, cursor + tam);
    cursor += tam;
    const grupo = grupos[idx % grupos.length];
    saida.equipes.push({
      numero: idx + 1,
      nome: nomeEquipe(idx),
      local: 'Cia ' + grupo.nome, // origem do script: cada equipe ocupa um local
      cia: grupo.nome,
      cidades: grupo.cidades,
      ciUnidas: grupo.unida,
      viatura: 'VTR-' + String(idx + 1).padStart(2, '0'),
      patrulhamento: true,
      membros: escalarFuncoes(membros),
      minima: tam <= MINIMO_EQUIPE,
    });
  });
  const sobra = fila.slice(cursor);
  saida.semLocal = sobra.map((p) => ({ ...p, motivo: AVISO_SOZINHO }));
  saida.aviso = sobra.length ? AVISO_SOZINHO : '';
  return saida;
}

// nome do membro com a posição dentro da equipe (P1, P2, P3...)
function composicaoEquipe(eq) {
  return (eq.membros || []).map((m) => `${m.posicao} ${m.nome}`).join(' · ');
}
function textoEquipe(eq) {
  return `${eq.nome} — ${composicaoEquipe(eq)} (${eq.cia} · ${eq.viatura} · ${eq.cidades})`;
}
// id do membro -> equipe|posição, pra saber quem mudou de lugar
function assinaturaMembros(calc) {
  const mapa = {};
  (calc.equipes || []).forEach((e) => (e.membros || []).forEach((m) => { mapa[m.id] = e.nome + '|' + m.posicao; }));
  return mapa;
}

// marca cada pessoa na base com a equipe/posição e quem está esperando vaga
function marcarStatusEquipes(s) {
  const mapa = new Map();
  (s.equipes || []).forEach((e) => (e.membros || []).forEach((m) => mapa.set(m.id, {
    equipe: e.nome, equipeNumero: e.numero, posicao: m.posicao, viatura: e.viatura, cia: e.cia, cidades: e.cidades,
  })));
  s.equipeDe = {};
  mapa.forEach((v, k) => { s.equipeDe[k] = v; });
  s.presentes = (s.presentes || []).map((p) => {
    const info = mapa.get(p.id);
    return info
      ? { ...p, ...info, aguardando: false, situacao: 'Em serviço' }
      : { ...p, aguardando: true, situacao: s.formada ? 'Aguardando vaga' : 'Aguardando equipe' };
  });
  s.quadro = (s.equipes || []).map((e) => ({ nome: e.nome, texto: composicaoEquipe(e), cia: e.cia, viatura: e.viatura }));
  return s;
}

// o que o próprio operador precisa ver: ponto batido? em equipe? esperando?
function statusDoOperador(usuario, calc) {
  if (!usuario) return null;
  const p = pontoAbertoDe(usuario.id);
  const naBase = (calc.presentes || []).find((x) => x.id === usuario.id);
  if (naBase) {
    if (naBase.equipe) {
      return {
        naBase: true, pontoAberto: true, entradaPonto: naBase.entradaPonto, aguardando: false,
        equipe: naBase.equipe, posicao: naBase.posicao, viatura: naBase.viatura, cia: naBase.cia, cidades: naBase.cidades,
        texto: `Ponto batido às ${horaBR(naBase.entradaPonto)}. Escalação: ${naBase.equipe} — ${naBase.posicao} · ${naBase.cia} · ${naBase.viatura} · Patrulhamento.`,
      };
    }
    return {
      naBase: true, pontoAberto: true, entradaPonto: naBase.entradaPonto, aguardando: true, equipe: null,
      texto: `Ponto batido às ${horaBR(naBase.entradaPonto)}. Você está na base aguardando o Comando formar a equipe. Assim que sair, você recebe o aviso com a sua posição.`,
    };
  }
  if (!p) {
    return { naBase: false, pontoAberto: false, aguardando: false, equipe: null,
      texto: 'Você não está com o ponto batido. Bata o ponto para ficar na base e entrar em equipe.' };
  }
  if (usuario.suspensoAte && new Date(usuario.suspensoAte).getTime() > Date.now()) {
    return { naBase: false, pontoAberto: true, entradaPonto: p.entrada, aguardando: false, equipe: null,
      texto: `Ponto batido às ${horaBR(p.entrada)}, mas você está suspenso até ${horaBR(usuario.suspensoAte)} e não entra em equipe.` };
  }
  const sol = solicitacaoVigente(usuario.id, ['afastamento', 'folga']);
  if (sol) {
    return { naBase: false, pontoAberto: true, entradaPonto: p.entrada, aguardando: false, equipe: null,
      texto: `Ponto batido às ${horaBR(p.entrada)}, mas hoje você está de ${sol.tipo === 'folga' ? 'folga' : 'afastamento'} (aprovado pelo comando) e não entra em equipe.` };
  }
  return { naBase: false, pontoAberto: true, entradaPonto: p.entrada, aguardando: false, equipe: null,
    texto: `Ponto batido às ${horaBR(p.entrada)}, mas você não está disponível para equipe agora.` };
}

// monta as equipes agora, com quem está na base neste instante
function calcularEquipes() {
  return marcarStatusEquipes(calcularEquipesCru());
}

// aviso de equipe formada/atualizada: cada um recebe a escalação P1/P2/P3,
// e quem comanda o serviço recebe o quadro completo da unidade.
function avisarEquipes(calc, quem, tipo) {
  if (!calc || !calc.formada) return;
  const titulo = tipo === 'mudou' ? '🚔 Equipe atualizada' : '🚔 Equipe formada';
  const quadro = (calc.equipes || []).map(textoEquipe);
  const resumo = `${calc.unidade}: ${quadro.join(' | ')}`.slice(0, 450);
  (calc.equipes || []).forEach((eq) => {
    const comp = composicaoEquipe(eq);
    eq.membros.forEach((m) => {
      if (quem && m.id === quem.id) return;
      notificar(m.id, titulo,
        `${eq.nome} — você é ${m.posicao}. ${comp}. ${eq.cia} · ${eq.viatura} · Patrulhamento${eq.ciUnidas ? ' (Cias unidas)' : ''}.`);
    });
    enviarPush(eq.membros.map((m) => m.id), titulo, `${eq.nome} · ${comp}`);
  });
  const emEquipe = new Set();
  (calc.equipes || []).forEach((e) => (e.membros || []).forEach((m) => emEquipe.add(m.id)));
  db.users
    .filter((u) => u && u.ativo && pode(u, 'equipes') && !emEquipe.has(u.id) && (!quem || u.id !== quem.id))
    .forEach((u) => notificar(u.id, titulo === '🚔 Equipe atualizada' ? '🚔 Equipes atualizadas' : '🚔 Equipes formadas', resumo));
  if ((calc.semLocal || []).length) {
    calc.semLocal.forEach((m) => {
      if (quem && m.id === quem.id) return;
      notificar(m.id, 'Você está sem equipe', AVISO_SOZINHO + '.');
    });
  }
  if (!db.config.equipesAviso || typeof db.config.equipesAviso !== 'object') db.config.equipesAviso = {};
  db.config.equipesAviso[calc.unidade] = assinaturaMembros(calc);
  saveDB();
}

// reposição automática: alguém bateu ponto ou saiu, a vaga é ocupada sozinha
// e quem mudou de lugar recebe o aviso com a nova escalação.
function avisarReposicaoEquipes() {
  try {
    const codigo = codigoUnidade();
    if (!formacaoDaUnidade(codigo)) return;
    const calc = calcularEquipes();
    if (!calc.formada || calc.modo === 'manual') return;
    if (!db.config.equipesAviso || typeof db.config.equipesAviso !== 'object') db.config.equipesAviso = {};
    const antes = db.config.equipesAviso[codigo] || {};
    const agoraMap = assinaturaMembros(calc);
    let mudou = false;
    Object.keys(agoraMap).forEach((id) => {
      if (antes[id] === agoraMap[id]) return;
      const eq = (calc.equipes || []).find((e) => (e.membros || []).some((m) => m.id === id));
      if (!eq) return;
      const m = eq.membros.find((x) => x.id === id);
      notificar(id, '🚔 Sua equipe foi atualizada', `${eq.nome} — você é ${m.posicao}. ${composicaoEquipe(eq)}. ${eq.cia} · ${eq.viatura}.`);
      enviarPush([id], 'Equipe atualizada', `${eq.nome} · ${m.posicao}`);
      mudou = true;
    });
    db.config.equipesAviso[codigo] = agoraMap;
    if (mudou) saveDB();
  } catch (_) { /* nunca derruba o ponto por causa do aviso */ }
}

// ───────── ponto fecha sozinho à meia-noite (horário da base) ─────────
function fecharPontosDaMeiaNoite() {
  if (!db || !Array.isArray(db.ponto)) return;
  const agoraMs = Date.now();
  const local = agoraMs + TURNOS_MS;
  const inicioDoDiaLocal = Math.floor(local / 86400000) * 86400000;
  const limiteMs = inicioDoDiaLocal - TURNOS_MS; // 00:00 de hoje no horário da base
  let mudou = false;
  db.ponto.forEach((p) => {
    if (!p || p.saida) return;
    const entrada = new Date(p.entrada).getTime();
    if (!Number.isFinite(entrada) || entrada >= limiteMs) return;
    if (Array.isArray(p.pausas)) {
      const aberta = p.pausas.find((x) => !x.ate);
      if (aberta) aberta.ate = new Date(limiteMs).toISOString();
    }
    p.pausadoEm = null;
    p.saida = new Date(limiteMs).toISOString();
    p.minutos = Math.max(1, minutosTrabalhados(p));
    p.minutosPausados = Math.round(msPausados(p) / 60000);
    p.fechadoAuto = true;
    const u = db.users.find((x) => x.id === p.userId);
    if (u) {
      notificar(u.id, 'Ponto encerrado automaticamente',
        'O ponto do dia foi fechado sozinho à meia-noite (' + p.minutos + ' min trabalhados).');
    }
    log(u ? u.login : p.login, 'PONTO_FECHADO_AUTO', 'meia-noite | ' + (p.minutos || 0) + ' min');
    mudou = true;
  });
  if (mudou) saveDB();
}

// ───────── prova trancada (antifraude) ─────────
// A prova objetiva é lançada em "modo trancado": o policial inicia, a prova abre
// em tela cheia e, se ele sair do app, trocar de aba, minimizar, recarregar ou
// fechar o navegador, a entrega é reprovada na hora, sem chance de voltar.
const PROVA_SINAL_MS = 45000; // ficou 45s sem sinal = app fechado, celular morreu ou internet caiu

const MOTIVOS_SAIDA = {
  saiu_do_app: 'Saiu do aplicativo durante a prova',
  trocou_aba: 'Trocou de aba ou minimizou o aplicativo durante a prova',
  fechou_app: 'Fechou ou recarregou o aplicativo durante a prova',
  saiu_tela_cheia: 'Saiu da tela cheia durante a prova',
  voltou: 'Tentou voltar/sair da tela da prova',
  desistiu: 'Desistiu da prova',
  sinal_perdido: 'Perdeu a conexão com o sistema durante a prova',
};
function motivoSaida(chave) {
  return MOTIVOS_SAIDA[String(chave || '')] || 'Saiu do aplicativo durante a prova';
}
function entregaAberta(userId) {
  return (db.entregas || []).find((e) => e.userId === userId && e.status === 'Em andamento') || null;
}
// reprova a entrega na hora (sem nota, com o motivo registrado)
function reprovarProvaAuto(entrega, motivo, evento) {
  if (!entrega || entrega.status !== 'Em andamento') return false;
  entrega.status = 'Reprovada';
  if (!entrega.em) entrega.em = agora();
  entrega.nota = null;
  entrega.percentual = null;
  entrega.corrigidaAuto = true;
  entrega.avaliadoPor = 'automático (antifraude)';
  entrega.avaliadoEm = agora();
  entrega.reprovadaAuto = true;
  entrega.motivoReprovacao = String(motivo || 'Saiu do aplicativo durante a prova').slice(0, 300);
  entrega.respostas = 'Prova encerrada automaticamente — ' + entrega.motivoReprovacao + '.';
  entrega.eventos = Array.isArray(entrega.eventos) ? entrega.eventos : [];
  if (evento) entrega.eventos.push({ tipo: String(evento).slice(0, 40), em: agora() });
  registrarDecisaoProva(entrega);
  return true;
}
// avisa o policial, os avaliadores e a auditoria
function avisarReprovacaoAuto(entrega) {
  if (!entrega) return;
  const dono = db.users.find((u) => u.id === entrega.userId);
  notificar(entrega.userId, 'Prova reprovada automaticamente',
    entrega.provaTitulo + ': ' + entrega.motivoReprovacao + '.');
  db.users.filter((u) => u.ativo && u.id !== entrega.userId && pode(u, 'provasAvaliar')).forEach((u) => {
    notificar(u.id, 'Prova reprovada na hora (antifraude)',
      entrega.nome + ' (@' + entrega.login + ') — ' + entrega.provaTitulo + ': ' + entrega.motivoReprovacao + '.');
  });
  enviarPush([entrega.userId], 'Prova reprovada', entrega.motivoReprovacao);
  log(dono ? dono.login : entrega.login, 'PROVA_REPROVADA_AUTO', entrega.provaTitulo + ' | ' + entrega.motivoReprovacao);
}
// fecha sozinha a prova que ficou aberta sem sinal (app fechado, celular desligado, internet caída)
function varrerProvasEmAndamento() {
  if (!db || !Array.isArray(db.entregas) || !db.entregas.length) return;
  const agoraMs = Date.now();
  let mudou = false;
  db.entregas.forEach((e) => {
    if (!e || e.status !== 'Em andamento') return;
    const ultimo = Number(e.ultimoSinal) || Number(e.iniciadaEmMs) || 0;
    if (ultimo && agoraMs - ultimo > PROVA_SINAL_MS) {
      if (reprovarProvaAuto(e, motivoSaida('sinal_perdido'), 'sinal_perdido')) {
        avisarReprovacaoAuto(e);
        mudou = true;
      }
    }
  });
  if (mudou) saveDB();
}

// ───────── rotas ─────────
async function api(req, res, seg) {
  const metodo = req.method;
  varrerProvasEmAndamento();
  fecharPontosDaMeiaNoite();

  // ---- login ----
  if (seg === 'login' && metodo === 'POST') {
    const { login, senha } = await lerCorpo(req);
    const u = db.users.find((x) => String(x.login).toLowerCase() === String(login || '').trim().toLowerCase());
    if (!u || !checaSenha(senha, u.senha)) {
      log(login || '?', 'LOGIN_FALHOU', 'senha ou login incorreto');
      return json(res, 401, { error: 'Login ou senha incorretos.' });
    }
    if (!u.ativo) return json(res, 403, { error: 'Conta desativada. Procure um superior.' });
    if (u.suspensoAte && new Date(u.suspensoAte).getTime() > Date.now()) {
      return json(res, 403, {
        suspenso: true,
        restanteMs: new Date(u.suspensoAte).getTime() - Date.now(),
        motivo: u.suspensaoMotivo,
        aplicadoPor: u.suspensaoPor,
        expiraEm: u.suspensoAte,
      });
    }
    if (u.suspensoAte && new Date(u.suspensoAte).getTime() <= Date.now()) {
      u.suspensoAte = null; u.suspensaoMotivo = null; u.suspensaoPor = null;
    }
    u.ultimoAcesso = agora();
    saveDB();
    const token = criaSessao(u.id);
    log(u.login, 'LOGIN', 'acesso autenticado');
    return json(res, 200, { token, user: publico(u) });
  }

  // ---- identidade pública (usada na tela de login e no menu do celular) ----
  if (seg === 'identidade' && metodo === 'GET') {
    return json(res, 200, configPublico());
  }

  // ---- bot do Discord (sem login: quem chama é o próprio bot, com o token dele) ----
  if (seg === 'bot/canal' && metodo === 'GET') {
    const b = botDoConfig();
    return json(res, 200, { canal: b.canal, ligado: b.ligado, intervalo: 10 });
  }

  if (seg === 'bot/avisos' && metodo === 'GET') {
    if (!(await botAutorizado(req))) return json(res, 401, { error: 'Token do bot não aceito pelo Discord.' });
    const b = botDoConfig();
    if (!b.canal || !b.ligado) return json(res, 200, { canal: b.canal, ligado: b.ligado, avisos: [] });
    botMarcarContato();
    return json(res, 200, { canal: b.canal, ligado: b.ligado, sistema: (db.config && db.config.nomeSistema) || 'POLÍCIA FEDERAL', avisos: avisosParaBot() });
  }

  if (seg === 'bot/entregues' && metodo === 'POST') {
    if (!(await botAutorizado(req))) return json(res, 401, { error: 'Token do bot não aceito pelo Discord.' });
    const b = await lerCorpo(req);
    botEntregues(b.entregues, b.permanentes, b.erro);
    return json(res, 200, { ok: true, fila: filaBot().length });
  }

  if (seg === 'bot/status' && metodo === 'POST') {
    if (!(await botAutorizado(req))) return json(res, 401, { error: 'Token do bot não aceito pelo Discord.' });
    const b = await lerCorpo(req);
    if (!db.config.discord || !db.config.discord.bot) return json(res, 200, { ok: true });
    if (b.nome) db.config.discord.bot.nome = String(b.nome).slice(0, 80);
    if (b.id) db.config.discord.bot.id = String(b.id).replace(/[^0-9]/g, '').slice(0, 32);
    db.config.discord.bot.ultimoContato = Date.now();
    saveDB();
    return json(res, 200, { ok: true, canal: botDoConfig().canal, ligado: botDoConfig().ligado });
  }

  // ---- daqui pra baixo exige sessão ----
  const eu = usuarioDaReq(req);
  if (!eu) return json(res, 401, { error: 'Sessão expirada. Faça login novamente.' });
  const corpo = metodo === 'GET' || metodo === 'DELETE' && seg.startsWith('users/') ? {} : {};

  if (seg === 'logout' && metodo === 'POST') {
    const h = req.headers['authorization'] || '';
    sessoes.delete(h.slice(7));
    return json(res, 200, { ok: true });
  }

  if (seg === 'me' && metodo === 'GET') return json(res, 200, { user: publico(eu) });

  if (seg === 'state' && metodo === 'GET') {
    const meuNivel = nivel(eu.cargo);
    return json(res, 200, {
      config: configPublico(),
      discord: (ehMaster(eu) || pode(eu, 'identidade')) ? estadoDiscord() : null,
      cargos: listaCargos(),
      minhasPermissoes: permissoesDe(eu),
      catalogoPermissoes: PERMISSOES.map((p) => ({ chave: p.chave, label: p.label })),
      souMaster: ehMaster(eu),
      users: db.users.map(publico),
      ocorrencias: ocorrenciasPublicas(),
      pontos: db.pontos,
      chat: db.chat.slice(-200),
      chatLideres: pode(eu, 'chatLideres') ? db.chatLideres.slice(-200) : [],
      solicitacoes: (pode(eu, 'solicitacoesResponder') ? db.solicitacoes : db.solicitacoes.filter((x) => x.userId === eu.id)).slice(0, 200),
      ticketOpcoes: db.ticketOpcoes,
      tickets: (pode(eu, 'ticketsResponder') ? db.tickets : db.tickets.filter((x) => x.userId === eu.id)).slice(0, 300),
      advertencias: (pode(eu, 'advertencias') ? db.advertencias : db.advertencias.filter((x) => x.userId === eu.id)).slice(0, 200),
      cursos: (pode(eu, 'cursos') ? db.cursos : db.cursos.filter((x) => x.userId === eu.id)).slice(0, 200),
      turnos: db.turnos.slice(-150),
      avisosCelular: (db.push || []).some((p) => p.userId === eu.id),
      audit: pode(eu, 'auditoria') ? db.audit.slice(0, 300) : db.audit.filter((a) => a.feitorPor === eu.login).slice(0, 50),
      notificacoes: db.notificacoes.filter((n) => n.para === eu.id).slice(0, 100),
      provas: (pode(eu, 'provasLancar') || pode(eu, 'provasAvaliar'))
        ? db.provas
        : db.provas.filter((p) => provaPara(eu, p) || p.criadoPor === eu.login).map(semGabarito),
      tiposProva: [...new Set(db.provas.map((p) => p.tipo || 'Geral'))].sort(),
      entregas: pode(eu, 'provasAvaliar') ? db.entregas : db.entregas.filter((e) => e.userId === eu.id),
      aprovacoes: db.aprovacoes.slice(0, 400),
      equipes: (() => { const c = calcularEquipes(); c.meu = statusDoOperador(eu, c); return c; })(),
      ponto: (pode(eu, 'pontoTodos') ? db.ponto : db.ponto.filter((p) => p.userId === eu.id)).slice(0, 300),
      estudos: db.estudos,
      estudosLidos: db.estudosLidos,
      regras: db.config.regras || '',
      codigosQ: db.config.codigosQ || [],
      bancoLigado: !!pool,
      funcionarioMes: rankingPonto(),
      meuNivel,
    });
  }

  // ---- perfil ----
  if (seg === 'me/perfil' && metodo === 'PUT') {
    const b = await lerCorpo(req);
    if (typeof b.nome === 'string' && b.nome.trim()) eu.nome = b.nome.trim().slice(0, 60);
    if (typeof b.recado === 'string') eu.recado = b.recado.slice(0, 200);
    if (typeof b.foto === 'string') {
      if (b.foto.length > 900000) return json(res, 400, { error: 'Foto muito grande (máx ~600KB).' });
      eu.foto = b.foto || null;
    }
    saveDB();
    log(eu.login, 'PERFIL_ATUALIZADO', 'dados do próprio perfil');
    return json(res, 200, { user: publico(eu) });
  }

  if (seg === 'me/senha' && metodo === 'PUT') {
    const b = await lerCorpo(req);
    if (!checaSenha(b.atual, eu.senha)) return json(res, 400, { error: 'Senha atual incorreta.' });
    if (!b.nova || String(b.nova).length < 4) return json(res, 400, { error: 'Nova senha muito curta (mín. 4).' });
    eu.senha = hashSenha(b.nova);
    saveDB();
    log(eu.login, 'SENHA_ALTERADA', 'o próprio usuário trocou a senha');
    return json(res, 200, { ok: true });
  }

  // ---- usuários (gestão) ----
  if (seg === 'users' && metodo === 'POST') {
    if (!pode(eu, 'usuariosCriar')) return json(res, 403, { error: 'Seu cargo não pode cadastrar membros.' });
    const b = await lerCorpo(req);
    const login = String(b.login || '').trim();
    if (!login || !b.nome || !b.senha) return json(res, 400, { error: 'Nome, login e senha são obrigatórios.' });
    if (db.users.some((u) => u.login.toLowerCase() === login.toLowerCase())) return json(res, 400, { error: 'Este login já existe.' });
    const cargoPedido = String(b.cargo || '').trim();
    const cargosAgora = listaCargos();
    if (cargoPedido && !cargosAgora.some((c) => c.nome === cargoPedido)) return json(res, 400, { error: 'Cargo inválido: ' + cargoPedido });
    const cargo = cargosAgora.some((c) => c.nome === cargoPedido)
      ? cargoPedido
      : (cargosAgora[cargosAgora.length - 1] || { nome: 'Civil' }).nome;
    if (nivel(cargo) >= nivel(eu.cargo) && !ehMaster(eu)) return json(res, 403, { error: 'Não pode criar alguém do seu nível ou acima.' });
    const novo = {
      id: uid(), nome: String(b.nome).slice(0, 60), login, senha: hashSenha(b.senha), cargo,
      ativo: true, suspensoAte: null, suspensaoMotivo: null, suspensaoPor: null,
      pontos: 0, foto: null, recado: '', criadoEm: agora(), ultimoAcesso: null,
    };
    db.users.push(novo);
    saveDB();
    log(eu.login, 'USUARIO_CRIADO', `${login} como ${cargo}`);
    notificar(novo.id, 'Bem-vindo ao sistema', `Sua conta foi criada por ${eu.nome}.`);
    return json(res, 200, { user: publico(novo) });
  }

  const mUser = seg.match(/^users\/([a-f0-9]+)(?:\/(.+))?$/);
  if (mUser) {
    const alvo = db.users.find((u) => u.id === mUser[1]);
    if (!alvo) return json(res, 404, { error: 'Usuário não encontrado.' });
    const acao = mUser[2] || '';
    const souEu = alvo.id === eu.id;
    const superior = nivel(eu.cargo) > nivel(alvo.cargo) || ehMaster(eu);

    if (!acao && metodo === 'DELETE') {
      if (!pode(eu, 'usuariosGerir') || !superior) return json(res, 403, { error: 'Sem permissão para excluir este usuário.' });
      db.users = db.users.filter((u) => u.id !== alvo.id);
      db.solicitacoes = db.solicitacoes.filter((x) => x.userId !== alvo.id);
      db.advertencias = db.advertencias.filter((x) => x.userId !== alvo.id);
      db.cursos = db.cursos.filter((x) => x.userId !== alvo.id);
      db.push = db.push.filter((x) => x.userId !== alvo.id);
      db.turnos.forEach((t) => { if (Array.isArray(t.membros)) t.membros = t.membros.filter((id) => id !== alvo.id); });
      saveDB();
      log(eu.login, 'USUARIO_EXCLUIDO', alvo.login);
      return json(res, 200, { ok: true });
    }

    if (acao === 'cargo' && metodo === 'PUT') {
      if (!pode(eu, 'usuariosGerir') && !pode(eu, 'promover')) return json(res, 403, { error: 'Sem permissão para alterar cargo.' });
      const b = await lerCorpo(req);
      if (!listaCargos().some((c) => c.nome === b.cargo)) return json(res, 400, { error: 'Cargo inválido.' });
      if (nivel(b.cargo) >= nivel(eu.cargo) && !ehMaster(eu)) return json(res, 403, { error: 'Não pode promover a um nível igual ou acima do seu.' });
      const antes = alvo.cargo;
      const motivo = String(b.motivo || '').trim().slice(0, 200);
      if (antes === b.cargo) return json(res, 200, { user: publico(alvo), tipo: '' });
      const nAntes = nivel(antes);
      const nDepois = nivel(b.cargo);
      const tipo = nDepois > nAntes ? 'promocao' : (nDepois < nAntes ? 'rebaixamento' : '');
      alvo.cargo = b.cargo;
      saveDB();
      const acaoLog = tipo === 'promocao' ? 'PROMOCAO' : (tipo === 'rebaixamento' ? 'REBAIXAMENTO' : 'CARGO_ALTERADO');
      log(eu.login, acaoLog, `${alvo.login}: ${antes} -> ${b.cargo}${motivo ? ' | motivo: ' + motivo : ''}`);
      const rotulo = tipo === 'promocao' ? 'Promoção' : (tipo === 'rebaixamento' ? 'Rebaixamento' : 'Seu cargo mudou');
      notificar(alvo.id, rotulo, `${antes} → ${b.cargo}${motivo ? ' (motivo: ' + motivo + ')' : ''} · por ${eu.nome}`);
      enviarPush([alvo.id], rotulo, `${eu.nome}: ${antes} → ${b.cargo}`);
      let noDiscord = null;
      if (tipo) {
        noDiscord = avisarCargoNoDiscord({
          tipo, nome: alvo.nome, login: alvo.login, de: antes, para: b.cargo,
          por: eu.nome, porLogin: eu.login, motivo,
          advertencias: totalAdvertencias(alvo.id), em: agora(),
        });
      }
      return json(res, 200, { user: publico(alvo), tipo, aviso: noDiscord && noDiscord.naFila ? 'fila' : '' });
    }

    if (acao === 'senha' && metodo === 'PUT') {
      if (!pode(eu, 'usuariosGerir') || !superior) return json(res, 403, { error: 'Sem permissão para redefinir esta senha.' });
      const b = await lerCorpo(req);
      if (!b.novaSenha || String(b.novaSenha).length < 4) return json(res, 400, { error: 'Senha muito curta (mín. 4).' });
      alvo.senha = hashSenha(b.novaSenha);
      saveDB();
      log(eu.login, 'SENHA_REDEFINIDA', `senha de ${alvo.login} redefinida`);
      return json(res, 200, { ok: true });
    }

    if (acao === 'status' && metodo === 'PUT') {
      if (!pode(eu, 'usuariosGerir') || !superior) return json(res, 403, { error: 'Sem permissão.' });
      const b = await lerCorpo(req);
      alvo.ativo = !!b.ativo;
      saveDB();
      log(eu.login, alvo.ativo ? 'USUARIO_ATIVADO' : 'USUARIO_DESATIVADO', alvo.login);
      return json(res, 200, { user: publico(alvo) });
    }

    if (acao === 'suspensao' && metodo === 'PUT') {
      if (!pode(eu, 'usuariosGerir') || !superior) return json(res, 403, { error: 'Sem permissão.' });
      const b = await lerCorpo(req);
      if (b.minutos === 0 || b.minutos === null) {
        alvo.suspensoAte = null; alvo.suspensaoMotivo = null; alvo.suspensaoPor = null;
        saveDB();
        log(eu.login, 'SUSPENSAO_REMOVIDA', alvo.login);
        return json(res, 200, { user: publico(alvo) });
      }
      const min = Math.max(1, Math.min(43200, Number(b.minutos) || 0));
      alvo.suspensoAte = new Date(Date.now() + min * 60000).toISOString();
      alvo.suspensaoMotivo = String(b.motivo || '—').slice(0, 200);
      alvo.suspensaoPor = eu.login;
      saveDB();
      log(eu.login, 'SUSPENSAO_APLICADA', `${alvo.login} por ${min} min | motivo: ${alvo.suspensaoMotivo}`);
      return json(res, 200, { user: publico(alvo) });
    }

    if (acao === 'ban' && metodo === 'PUT') {
      if (!pode(eu, 'usuariosGerir') || !superior) return json(res, 403, { error: 'Sem permissão para banir.' });
      const b = await lerCorpo(req);
      alvo.ativo = false;
      alvo.suspensoAte = new Date(Date.now() + 365 * 24 * 3600 * 1000).toISOString();
      alvo.suspensaoMotivo = String(b.motivo || 'Banimento').slice(0, 200);
      alvo.suspensaoPor = eu.login;
      saveDB();
      log(eu.login, 'BANIMENTO', `${alvo.login} | motivo: ${alvo.suspensaoMotivo}`);
      return json(res, 200, { user: publico(alvo) });
    }
  }

  // ---- ocorrências ----
  // Guarda Municipal, Agente e Tático não registram ocorrência.
  if (seg === 'ocorrencias' && metodo === 'POST') {
    if (!pode(eu, 'ocorrencias')) {
      return json(res, 403, { error: 'Seu cargo não tem permissão para registrar ocorrência. Fale com um superior.' });
    }
    const b = await lerCorpo(req);
    if (!b.titulo && !b.agente) return json(res, 400, { error: 'Informe o agente/título da ocorrência.' });
    const foto = validaFotoOcorrencia(b.foto);
    if (foto === false) return json(res, 400, { error: 'Foto inválida ou muito grande (máx 2 MB). Use uma imagem JPG/PNG.' });
    const oc = {
      id: uid(),
      foto: foto || null,
      fotoV: foto ? Date.now() : null,
      titulo: String(b.titulo || b.agente || 'Ocorrência').slice(0, 120),
      agente: String(b.agente || eu.nome).slice(0, 60),
      cargoAgente: String(b.cargoAgente || eu.cargo).slice(0, 40),
      status: 'Pendente',
      responsavel: '',
      depoimento: String(b.depoimento || '').slice(0, 4000),
      resposta: '',
      criadoPor: eu.login,
      criadoEm: agora(),
      atualizadoEm: agora(),
    };
    db.ocorrencias.unshift(oc);
    saveDB();
    log(eu.login, 'OCORRENCIA_CRIADA', oc.titulo);
    return json(res, 200, { ocorrencia: oc });
  }

  const mOc = seg.match(/^ocorrencias\/([a-f0-9]+)$/);
  if (mOc) {
    const oc = db.ocorrencias.find((o) => o.id === mOc[1]);
    if (!oc) return json(res, 404, { error: 'Ocorrência não encontrada.' });
    const podeMexer = pode(eu, 'ocorrencias') || oc.criadoPor === eu.login;
    if (metodo === 'PUT') {
      if (!podeMexer) return json(res, 403, { error: 'Sem permissão para editar esta ocorrência.' });
      const b = await lerCorpo(req);
      ['titulo', 'agente', 'cargoAgente', 'status', 'responsavel', 'depoimento', 'resposta'].forEach((k) => {
        if (typeof b[k] === 'string') oc[k] = b[k].slice(0, k === 'depoimento' || k === 'resposta' ? 4000 : 120);
      });
      if (typeof b.foto === 'string') {
        if (b.foto === '') { oc.foto = null; oc.fotoV = null; }
        else {
          const foto = validaFotoOcorrencia(b.foto);
          if (foto === false) return json(res, 400, { error: 'Foto inválida ou muito grande (máx 2 MB).' });
          oc.foto = foto; oc.fotoV = Date.now();
        }
      }
      oc.atualizadoEm = agora();
      saveDB();
      log(eu.login, 'OCORRENCIA_EDITADA', `${oc.titulo} -> ${oc.status}`);
      return json(res, 200, { ocorrencia: oc });
    }
    if (metodo === 'DELETE') {
      if (!pode(eu, 'ocorrenciasExcluir')) return json(res, 403, { error: 'Sem permissão para excluir ocorrência.' });
      db.ocorrencias = db.ocorrencias.filter((o) => o.id !== oc.id);
      saveDB();
      log(eu.login, 'OCORRENCIA_EXCLUIDA', oc.titulo);
      return json(res, 200, { ok: true });
    }
  }

  // ---- pontos ----
  if (seg === 'pontos' && metodo === 'POST') {
    if (!pode(eu, 'pontos')) return json(res, 403, { error: 'Sem permissão para lançar pontos.' });
    const b = await lerCorpo(req);
    const alvo = db.users.find((u) => u.id === b.userId);
    if (!alvo) return json(res, 404, { error: 'Policial não encontrado.' });
    const delta = Number(b.delta);
    if (!Number.isFinite(delta) || delta === 0) return json(res, 400, { error: 'Informe uma quantidade de pontos válida.' });
    alvo.pontos = (alvo.pontos || 0) + delta;
    const reg = { id: uid(), userId: alvo.id, login: alvo.login, delta, motivo: String(b.motivo || '—').slice(0, 200), por: eu.login, em: agora() };
    db.pontos.unshift(reg);
    saveDB();
    log(eu.login, 'PONTOS', `${delta > 0 ? '+' : ''}${delta} para ${alvo.login} | ${reg.motivo}`);
    notificar(alvo.id, 'Seus pontos mudaram', `${delta > 0 ? '+' : ''}${delta} pontos (${reg.motivo}). Total: ${alvo.pontos}`);
    return json(res, 200, { user: publico(alvo), registro: reg });
  }

  // ---- aprovações: quem passou e quem reprovou ----
  if (seg === 'aprovacoes' && metodo === 'POST') {
    if (!pode(eu, 'aprovacoes')) return json(res, 403, { error: 'Seu cargo não registra quem passou ou reprovou.' });
    const b = await lerCorpo(req);
    const decisao = String(b.decisao) === 'Reprovado' ? 'Reprovado' : 'Aprovado';
    const alvo = b.userId ? db.users.find((u) => u.id === b.userId) : null;
    if (b.userId && !alvo) return json(res, 404, { error: 'Membro não encontrado.' });
    const nome = alvo ? alvo.nome : String(b.nome || '').trim().slice(0, 60);
    if (!nome) return json(res, 400, { error: 'Escolha quem passou ou quem reprovou.' });
    let reg = db.aprovacoes.find((a) => {
      if (a.origem !== 'manual') return false;
      if (alvo) return a.userId === alvo.id;
      return !a.userId && String(a.nome || '').toLowerCase() === nome.toLowerCase();
    });
    if (!reg) {
      reg = { id: uid(), origem: 'manual', userId: alvo ? alvo.id : null, nome, em: agora() };
      db.aprovacoes.unshift(reg);
    }
    reg.nome = nome;
    reg.login = alvo ? alvo.login : (reg.login || '');
    reg.cargo = alvo ? alvo.cargo : String(b.cargo || reg.cargo || '').slice(0, 40);
    reg.decisao = decisao;
    reg.motivo = String(b.motivo || '').trim().slice(0, 300);
    reg.por = eu.nome;
    reg.porLogin = eu.login;
    reg.em = agora();
    if (db.aprovacoes.length > 2000) db.aprovacoes.length = 2000;
    saveDB();
    log(eu.login, decisao === 'Aprovado' ? 'APROVADO' : 'REPROVADO', nome + (reg.motivo ? ' | ' + reg.motivo : ''));
    if (alvo && alvo.id !== eu.id) {
      notificar(alvo.id, decisao === 'Aprovado' ? 'Você foi aprovado' : 'Você foi reprovado',
        decisao === 'Aprovado' ? 'O comando registrou você como APROVADO.' + (reg.motivo ? ' ' + reg.motivo : '')
          : 'O comando registrou você como REPROVADO.' + (reg.motivo ? ' ' + reg.motivo : ''));
      enviarPush([alvo.id], decisao === 'Aprovado' ? 'Aprovado' : 'Reprovado', reg.motivo || nome);
    }
    return json(res, 200, { aprovacao: reg });
  }

  if (seg === 'aprovacoes/decisao' && metodo === 'POST') {
    if (!pode(eu, 'aprovacoes')) return json(res, 403, { error: 'Seu cargo não muda a decisão.' });
    const b = await lerCorpo(req);
    const reg = db.aprovacoes.find((a) => a.id === b.id);
    if (!reg) return json(res, 404, { error: 'Registro não encontrado.' });
    reg.decisao = String(b.decisao) === 'Reprovado' ? 'Reprovado' : 'Aprovado';
    reg.por = eu.nome;
    reg.porLogin = eu.login;
    reg.em = agora();
    if (typeof b.motivo === 'string' && b.motivo.trim()) reg.motivo = b.motivo.trim().slice(0, 300);
    saveDB();
    log(eu.login, reg.decisao === 'Aprovado' ? 'APROVADO' : 'REPROVADO', reg.nome + ' (decisão alterada)');
    const usuario = reg.userId ? db.users.find((u) => u.id === reg.userId) : null;
    if (usuario && usuario.id !== eu.id) {
      notificar(usuario.id, 'Sua situação mudou', 'O comando registrou você como ' + reg.decisao.toUpperCase() + '.');
      enviarPush([usuario.id], 'Sua situação mudou', reg.decisao);
    }
    return json(res, 200, { aprovacao: reg });
  }

  if (seg === 'aprovacoes/remover' && metodo === 'POST') {
    if (!pode(eu, 'aprovacoes')) return json(res, 403, { error: 'Seu cargo não apaga decisões.' });
    const b = await lerCorpo(req);
    const reg = db.aprovacoes.find((a) => a.id === b.id);
    if (!reg) return json(res, 404, { error: 'Registro não encontrado.' });
    db.aprovacoes = db.aprovacoes.filter((a) => a.id !== reg.id);
    saveDB();
    log(eu.login, 'APROVACAO_APAGADA', reg.nome + ' | ' + reg.decisao);
    return json(res, 200, { ok: true });
  }

  // ---- equipes: formar, desfazer e código da unidade ----
  if (seg === 'equipes/formar' && metodo === 'POST') {
    if (!pode(eu, 'equipes')) return json(res, 403, { error: 'Seu cargo não forma equipe.' });
    const b = await lerCorpo(req);
    const tamanho = TAMANHOS_EQUIPE.includes(Number(b.tamanho)) ? Number(b.tamanho) : LIMITE_EQUIPE;
    const viaturas = Math.max(1, Math.min(MAX_VIATURAS, Number(b.viaturas) || 1));
    const codigo = String(b.unidade || codigoUnidade()).trim().replace(/\s+/g, '-').slice(0, 30) || 'UNIDADE-01';
    db.config.codigoUnidade = codigo;
    let form = formacaoDaUnidade(codigo);
    if (!form) { form = { id: uid(), unidade: codigo }; db.equipes.push(form); }
    form.ativa = true;
    form.modo = 'auto';
    form.tamanho = tamanho;
    form.viaturas = viaturas;
    form.ordem = (Array.isArray(b.ordem) ? b.ordem : []).filter((id) => db.users.some((u) => u.id === id)).slice(0, 300);
    form.formadaPor = eu.nome;
    form.formadaPorLogin = eu.login;
    form.formadaEm = agora();
    saveDB();
    const calc = calcularEquipes();
    log(eu.login, 'EQUIPE_FORMADA', `${codigo}: tamanho ${tamanho}, ${viaturas} viatura(s), ${calc.equipes.length} equipe(s)`);
    avisarEquipes(calc, eu, 'formada');
    return json(res, 200, { equipes: calc });
  }

  if (seg === 'equipes/manual' && metodo === 'POST') {
    if (!pode(eu, 'equipes')) return json(res, 403, { error: 'Seu cargo não monta equipe.' });
    const b = await lerCorpo(req);
    const codigo = String(b.unidade || codigoUnidade()).trim().replace(/\s+/g, '-').slice(0, 30) || 'UNIDADE-01';
    const viaturas = Math.max(1, Math.min(MAX_VIATURAS, Number(b.viaturas) || 1));
    const tamanho = TAMANHOS_EQUIPE.includes(Number(b.tamanho)) ? Number(b.tamanho) : LIMITE_EQUIPE;
    const bruto = (b.escalacao && typeof b.escalacao === 'object' && !Array.isArray(b.escalacao)) ? b.escalacao : {};
    const escalacao = {};
    let ignorados = 0;
    Object.keys(bruto).forEach((id) => {
      const nome = String(bruto[id] || '');
      if (!NOMES_EQUIPES.includes(nome)) return;
      if (!db.users.some((u) => u.id === id)) { ignorados++; return; }
      escalacao[id] = nome;
    });
    db.config.codigoUnidade = codigo;
    let form = formacaoDaUnidade(codigo);
    if (!form) { form = { id: uid(), unidade: codigo }; db.equipes.push(form); }
    form.ativa = true;
    form.modo = 'manual';
    form.manual = escalacao;
    form.tamanho = tamanho;
    form.viaturas = viaturas;
    form.formadaPor = eu.nome;
    form.formadaPorLogin = eu.login;
    form.formadaEm = agora();
    saveDB();
    const calc = calcularEquipes();
    log(eu.login, 'EQUIPE_MANUAL', `${codigo}: ${calc.equipes.length} equipe(s) escalada(s) à mão, ${calc.semLocal.length} fora`);
    avisarEquipes(calc, eu, 'mudou');
    return json(res, 200, { equipes: calc, ignorados });
  }

  if (seg === 'equipes/sair' && metodo === 'POST') {
    if (!pode(eu, 'equipes')) return json(res, 403, { error: 'Seu cargo não desfaz equipe.' });
    const b = await lerCorpo(req);
    const codigo = String(b.unidade || codigoUnidade());
    const form = formacaoDaUnidade(codigo);
    if (form) { form.ativa = false; form.dissolvidaEm = agora(); saveDB(); }
    log(eu.login, 'EQUIPE_DESFEITA', codigo);
    return json(res, 200, { equipes: calcularEquipes() });
  }

  if (seg === 'equipes/unidade' && metodo === 'POST') {
    if (!pode(eu, 'equipes')) return json(res, 403, { error: 'Seu cargo não troca o código da unidade.' });
    const b = await lerCorpo(req);
    const codigo = String(b.unidade || '').trim().replace(/\s+/g, '-').slice(0, 30);
    if (codigo.length < 3) return json(res, 400, { error: 'Escreva um código de unidade com pelo menos 3 caracteres.' });
    db.config.codigoUnidade = codigo;
    saveDB();
    log(eu.login, 'UNIDADE_DEFINIDA', codigo);
    return json(res, 200, { equipes: calcularEquipes() });
  }

  // ---- provas (Chefe, Delegado e Admin Master lançam) ----
  if (seg === 'provas' && metodo === 'POST') {
    if (!pode(eu, 'provasLancar')) return json(res, 403, { error: 'Seu cargo não pode criar provas.' });
    const b = await lerCorpo(req);
    if (!b.titulo || !String(b.titulo).trim()) return json(res, 400, { error: 'Informe o título da prova.' });
    const tiposValidos = ['todos', 'cargo', 'membros'];
    const alvo = tiposValidos.includes(String(b.publicoAlvo)) ? String(b.publicoAlvo) : 'todos';
    const cargosAlvo = alvo === 'cargo' ? (Array.isArray(b.cargosAlvo) ? b.cargosAlvo : []).filter((c) => listaCargos().some((x) => x.nome === c)) : [];
    const membrosAlvo = alvo === 'membros' ? (Array.isArray(b.membrosAlvo) ? b.membrosAlvo : []).filter((id) => db.users.some((u) => u.id === id)) : [];
    if (alvo === 'cargo' && !cargosAlvo.length) return json(res, 400, { error: 'Escolha pelo menos um cargo para a prova.' });
    if (alvo === 'membros' && !membrosAlvo.length) return json(res, 400, { error: 'Escolha pelo menos um policial para a prova.' });
    const notaMinima = Math.max(0, Math.min(100, Number(b.notaMinima) || 60));
    const questoes = (Array.isArray(b.questoes) ? b.questoes : []).slice(0, 60).map((q) => {
      const alternativas = (Array.isArray(q && q.alternativas) ? q.alternativas : [])
        .map((a) => String(a == null ? '' : a).trim().slice(0, 400))
        .filter((a) => a.length > 0)
        .slice(0, 6);
      return {
        id: uid(),
        pergunta: String((q && q.pergunta) || '').trim().slice(0, 800),
        alternativas,
        correta: Number(q && q.correta),
      };
    }).filter((q) => q.pergunta && q.alternativas.length >= 2 && Number.isInteger(q.correta) && q.correta >= 0 && q.correta < q.alternativas.length);
    const perguntasTexto = String(b.perguntas || '').slice(0, 6000);
    if (!questoes.length && !perguntasTexto.trim()) {
      return json(res, 400, { error: 'Monte pelo menos 1 questão com 2 alternativas e a resposta certa marcada.' });
    }
    const prova = {
      id: uid(),
      tipo: String(b.tipo || 'Geral').trim().slice(0, 40) || 'Geral',
      publicoAlvo: alvo,
      cargosAlvo,
      membrosAlvo,
      titulo: String(b.titulo).trim().slice(0, 120),
      descricao: String(b.descricao || '').slice(0, 2000),
      perguntas: perguntasTexto,
      questoes,
      notaMinima,
      trancada: b.trancada !== false,
      prazo: b.prazo ? String(b.prazo).slice(0, 10) : null,
      criadoPor: eu.login,
      criadoPorNome: eu.nome,
      criadoEm: agora(),
      ativa: true,
    };
    db.provas.unshift(prova);
    saveDB();
    log(eu.login, 'PROVA_LANCADA', `[${prova.tipo}] ${prova.titulo}`);
    db.users.filter((u) => u.ativo && u.id !== eu.id && provaPara(u, prova)).forEach((u) => {
      notificar(u.id, `Nova prova de ${prova.tipo}`, prova.titulo + ' — veja em Provas.');
      enviarPush([u.id], `Nova prova de ${prova.tipo}`, prova.titulo);
    });
    return json(res, 200, { prova });
  }

  const mProva = seg.match(/^provas\/([a-f0-9]+)(?:\/(.+))?$/);
  if (mProva) {
    const prova = db.provas.find((p) => p.id === mProva[1]);
    if (!prova) return json(res, 404, { error: 'Prova não encontrada.' });
    const acao = mProva[2] || '';

    // ---- entrar na prova: tranca a tela e abre a entrega em andamento ----
    if (acao === 'iniciar' && metodo === 'POST') {
      if (!provaPara(eu, prova) && prova.criadoPor !== eu.login) {
        return json(res, 403, { error: 'Esta prova não é para você.' });
      }
      const jaEnviada = db.entregas.find((e) => e.provaId === prova.id && e.userId === eu.id);
      if (jaEnviada && jaEnviada.status !== 'Em andamento') {
        return json(res, 400, { error: 'Você já enviou esta prova.' });
      }
      const outra = entregaAberta(eu.id);
      if (outra && outra.provaId !== prova.id) {
        return json(res, 400, { error: 'Você já está no meio da prova "' + outra.provaTitulo + '". Termine ela primeiro.' });
      }
      let entrega = jaEnviada;
      if (entrega) {
        entrega.iniciadaEm = agora();
        entrega.iniciadaEmMs = Date.now();
        entrega.ultimoSinal = Date.now();
        entrega.trancada = prova.trancada !== false;
      } else {
        entrega = {
          id: uid(), provaId: prova.id, provaTitulo: prova.titulo, provaTipo: prova.tipo || 'Geral',
          userId: eu.id, login: eu.login, nome: eu.nome, cargo: eu.cargo,
          em: null, status: 'Em andamento', nota: null, feedback: '', avaliadoPor: null, avaliadoEm: null,
          trancada: prova.trancada !== false,
          iniciadaEm: agora(), iniciadaEmMs: Date.now(), ultimoSinal: Date.now(), eventos: [],
        };
        db.entregas.unshift(entrega);
      }
      saveDB();
      log(eu.login, 'PROVA_INICIADA', '[' + (prova.tipo || 'Geral') + '] ' + prova.titulo);
      db.users.filter((u) => u.ativo && u.id !== eu.id && pode(u, 'provasAvaliar')).forEach((u) => {
        notificar(u.id, 'Prova iniciada', eu.nome + ' (@' + eu.login + ') começou "' + prova.titulo + '" (modo trancado).');
      });
      return json(res, 200, { entrega, prova: semGabarito(prova) });
    }

    if (acao === 'entregar' && metodo === 'POST') {
      const b = await lerCorpo(req);
      const objetiva = Array.isArray(prova.questoes) && prova.questoes.length > 0;
      const trancada = objetiva && prova.trancada !== false;
      const anterior = db.entregas.find((e) => e.provaId === prova.id && e.userId === eu.id);
      if (anterior && anterior.reprovadaAuto) {
        return json(res, 400, { error: 'Esta prova já foi reprovada automaticamente (' + (anterior.motivoReprovacao || 'antifraude') + '). Fale com o comando.' });
      }
      if (anterior && anterior.status !== 'Em andamento') {
        return json(res, 400, { error: 'Você já enviou esta prova.' });
      }
      if (trancada) {
        if (!anterior) {
          return json(res, 400, { error: 'Esta prova é em modo trancado: comece pelo botão "Iniciar prova" na tela de Provas.' });
        }
        if (anterior.reprovadaAuto) {
          return json(res, 400, { error: 'Esta prova já foi reprovada automaticamente. Fale com o comando.' });
        }
        if (b.entregaId && String(b.entregaId) !== anterior.id) {
          return json(res, 400, { error: 'A prova desta tela não é mais a válida. Comece de novo pela lista de Provas.' });
        }
      }
      const entrega = anterior || {
        id: uid(), provaId: prova.id, provaTitulo: prova.titulo, provaTipo: prova.tipo || 'Geral',
        userId: eu.id, login: eu.login, nome: eu.nome, cargo: eu.cargo,
        em: agora(),
        status: 'Aguardando', nota: null, feedback: '', avaliadoPor: null, avaliadoEm: null,
      };
      entrega.em = agora();
      entrega.trancada = trancada;
      if (!anterior) db.entregas.unshift(entrega);

      if (objetiva) {
        const escolhas = (Array.isArray(b.respostasQuiz) ? b.respostasQuiz : []).map((x) => (x === null || x === undefined || x === '' ? null : Number(x)));
        if (escolhas.length !== prova.questoes.length) {
          return json(res, 400, { error: 'Responda todas as questões da prova antes de enviar.' });
        }
        if (escolhas.some((x) => x === null || !Number.isInteger(x))) {
          return json(res, 400, { error: 'Tem questão sem resposta marcada.' });
        }
        let acertos = 0;
        prova.questoes.forEach((q, i) => { if (escolhas[i] === q.correta) acertos++; });
        const total = prova.questoes.length;
        const percentual = Math.round((acertos / total) * 100);
        const minimo = Number.isFinite(prova.notaMinima) ? prova.notaMinima : 60;
        entrega.respostasQuiz = escolhas;
        entrega.acertos = acertos;
        entrega.totalQuestoes = total;
        entrega.percentual = percentual;
        entrega.nota = Math.round((percentual / 10) * 10) / 10;
        entrega.status = percentual >= minimo ? 'Aprovada' : 'Reprovada';
        entrega.corrigidaAuto = true;
        entrega.avaliadoPor = 'automático';
        entrega.avaliadoEm = agora();
        entrega.respostas = `Prova objetiva — ${acertos} de ${total} certas (${percentual}%).`;
        registrarDecisaoProva(entrega);
      } else {
        const respostas = String(b.respostas || '').trim();
        if (!respostas) return json(res, 400, { error: 'Escreva suas respostas antes de enviar.' });
        entrega.respostas = respostas.slice(0, 10000);
      }

      saveDB();

      if (objetiva) {
        log(eu.login, 'PROVA_CORRIGIDA', `${prova.titulo} | ${entrega.acertos}/${entrega.totalQuestoes} (${entrega.percentual}%) -> ${entrega.status}`);
        notificar(eu.id, 'Sua prova foi corrigida',
          `${prova.titulo}: ${entrega.acertos}/${entrega.totalQuestoes} certas (${entrega.percentual}%) — ${entrega.status}.`);
        db.users.filter((u) => u.ativo && pode(u, 'provasAvaliar') && u.id !== eu.id).forEach((u) => {
          notificar(u.id, 'Prova corrigida', `${eu.nome} (@${eu.login}) fez "${prova.titulo}": ${entrega.percentual}% — ${entrega.status}.`);
        });
      } else {
        log(eu.login, 'PROVA_ENTREGUE', prova.titulo);
        db.users.filter((u) => u.ativo && pode(u, 'provasAvaliar')).forEach((u) => {
          notificar(u.id, 'Prova entregue', `${eu.nome} (@${eu.login}) enviou "${prova.titulo}".`);
        });
      }

      const gabarito = objetiva ? prova.questoes.map((q) => q.correta) : null;
      return json(res, 200, { entrega, gabarito });
    }

    if (!acao && metodo === 'DELETE') {
      if (!pode(eu, 'provasLancar')) return json(res, 403, { error: 'Sem permissão para excluir provas.' });
      db.provas = db.provas.filter((p) => p.id !== prova.id);
      db.entregas = db.entregas.filter((e) => e.provaId !== prova.id);
      saveDB();
      log(eu.login, 'PROVA_EXCLUIDA', prova.titulo);
      return json(res, 200, { ok: true });
    }
  }

  // ---- prova trancada: sinal de vida e reprovação na hora ----
  const mEntAcao = seg.match(/^entregas\/([a-f0-9]+)\/(sinal|reprovar)$/);
  if (mEntAcao && metodo === 'POST') {
    const ent = db.entregas.find((e) => e.id === mEntAcao[1]);
    if (!ent) return json(res, 404, { error: 'Prova em andamento não encontrada.' });
    if (ent.userId !== eu.id) return json(res, 403, { error: 'Essa prova não é sua.' });

    if (mEntAcao[2] === 'sinal') {
      if (ent.status === 'Em andamento') { ent.ultimoSinal = Date.now(); saveDB(); }
      return json(res, 200, { ok: true, status: ent.status, motivo: ent.motivoReprovacao || null });
    }

    const b = await lerCorpo(req).catch(() => ({}));
    const q = new URLSearchParams(String(req.url || '').split('?')[1] || '');
    const chave = String((b && b.motivo) || q.get('motivo') || 'saiu_do_app').slice(0, 40);
    if (ent.status !== 'Em andamento') {
      return json(res, 200, { entrega: ent, reprovada: ent.status === 'Reprovada', motivo: ent.motivoReprovacao || null });
    }
    reprovarProvaAuto(ent, motivoSaida(chave), chave);
    saveDB();
    avisarReprovacaoAuto(ent);
    return json(res, 200, { entrega: ent, reprovada: true, motivo: ent.motivoReprovacao });
  }

  // ---- avaliar prova entregue ----
  const mEnt = seg.match(/^entregas\/([a-f0-9]+)$/);
  if (mEnt && metodo === 'PUT') {
    if (!pode(eu, 'provasAvaliar')) return json(res, 403, { error: 'Seu cargo não pode avaliar provas.' });
    const ent = db.entregas.find((e) => e.id === mEnt[1]);
    if (!ent) return json(res, 404, { error: 'Entrega não encontrada.' });
    const b = await lerCorpo(req);
    ent.status = b.status === 'Aprovada' ? 'Aprovada' : 'Reprovada';
    const n = Number(b.nota);
    ent.nota = Number.isFinite(n) && b.nota !== '' && b.nota != null ? Math.max(0, Math.min(10, n)) : null;
    ent.feedback = String(b.feedback || '').slice(0, 1000);
    ent.avaliadoPor = eu.login;
    ent.avaliadoEm = agora();
    registrarDecisaoProva(ent, ent.feedback);
    saveDB();
    log(eu.login, 'PROVA_AVALIADA', `${ent.login} | ${ent.provaTitulo} -> ${ent.status}${ent.nota != null ? ' | nota ' + ent.nota : ''}`);
    notificar(ent.userId, 'Sua prova foi avaliada',
      `${ent.provaTitulo}: ${ent.status}${ent.nota != null ? ' | nota ' + ent.nota : ''}${ent.feedback ? ' — ' + ent.feedback : ''}`);
    return json(res, 200, { entrega: ent });
  }

  // ---- bate ponto (entrada, pausar, despausar e finalizar) ----
  if (seg === 'ponto' && metodo === 'POST') {
    const b = await lerCorpo(req);
    let acao = String(b.acao || 'entrada').toLowerCase();
    if (acao === 'pausa') acao = 'pausar';
    if (acao === 'retomar' || acao === 'continuar') acao = 'despausar';
    if (acao === 'finalizar' || acao === 'fim') acao = 'saida';
    if (!['entrada', 'pausar', 'despausar', 'saida'].includes(acao)) acao = 'entrada';

    const aberto = db.ponto.find((p) => p.userId === eu.id && !p.saida);

    if (acao === 'entrada') {
      if (aberto) return json(res, 400, { error: 'Você já bateu entrada às ' + horaBR(aberto.entrada) + '. Finalize o ponto primeiro.' });
      const reg = {
        id: uid(), userId: eu.id, login: eu.login, nome: eu.nome, cargo: eu.cargo,
        entrada: agora(), saida: null, minutos: null,
        pausas: [], pausadoEm: null,
      };
      db.ponto.unshift(reg);
      if (db.ponto.length > 5000) db.ponto.length = 5000;
      saveDB();
      log(eu.login, 'PONTO_ENTRADA', 'entrada às ' + horaBR(reg.entrada));
      avisarReposicaoEquipes();
      return json(res, 200, { registro: reg, mensagem: 'Entrada registrada às ' + horaBR(reg.entrada) });
    }

    if (!aberto) return json(res, 400, { error: 'Você não tem ponto aberto. Bata a entrada primeiro.' });
    if (!Array.isArray(aberto.pausas)) aberto.pausas = [];

    if (acao === 'pausar') {
      if (aberto.pausadoEm) return json(res, 400, { error: 'O ponto já está pausado desde ' + horaBR(aberto.pausadoEm) + '.' });
      aberto.pausadoEm = agora();
      aberto.pausas.push({ de: aberto.pausadoEm, ate: null });
      saveDB();
      log(eu.login, 'PONTO_PAUSA', 'pausou às ' + horaBR(aberto.pausadoEm));
      return json(res, 200, { registro: aberto, mensagem: 'Ponto pausado às ' + horaBR(aberto.pausadoEm) });
    }

    if (acao === 'despausar') {
      if (!aberto.pausadoEm) return json(res, 400, { error: 'O ponto não está pausado.' });
      const hora = agora();
      const aberta = aberto.pausas.find((p) => !p.ate);
      if (aberta) aberta.ate = hora;
      else aberto.pausas.push({ de: aberto.pausadoEm, ate: hora });
      const pausadoMin = Math.round((new Date(hora) - new Date(aberto.pausadoEm)) / 60000);
      aberto.pausadoEm = null;
      saveDB();
      log(eu.login, 'PONTO_RETOMADO', `voltou às ${horaBR(hora)} | pausou ${pausadoMin} min`);
      return json(res, 200, { registro: aberto, mensagem: 'Serviço retomado às ' + horaBR(hora) });
    }

    // finalizar
    const horaSaida = agora();
    if (aberto.pausadoEm) {
      const aberta = aberto.pausas.find((p) => !p.ate);
      if (aberta) aberta.ate = horaSaida;
      aberto.pausadoEm = null;
    }
    aberto.saida = horaSaida;
    aberto.minutos = Math.max(1, minutosTrabalhados(aberto));
    aberto.minutosPausados = Math.round(msPausados(aberto) / 60000);
    saveDB();
    log(eu.login, 'PONTO_SAIDA', `saída às ${horaBR(aberto.saida)} | ${aberto.minutos} min trabalhados | ${aberto.minutosPausados} min de pausa`);
    avisarReposicaoEquipes();
    return json(res, 200, {
      registro: aberto,
      mensagem: `Ponto finalizado às ${horaBR(aberto.saida)} · ${aberto.minutos} min trabalhados`,
    });
  }

  // ---- estudos (material de estudo lançado pelo comando) ----
  if (seg === 'estudos' && metodo === 'POST') {
    if (!pode(eu, 'estudos')) return json(res, 403, { error: 'Seu cargo não publica estudos.' });
    const b = await lerCorpo(req);
    const titulo = String(b.titulo || '').trim();
    const conteudo = String(b.conteudo || '').trim();
    if (!titulo) return json(res, 400, { error: 'Informe o título do estudo.' });
    if (!conteudo) return json(res, 400, { error: 'Escreva o conteúdo do estudo.' });
    const estudo = {
      id: uid(),
      titulo: titulo.slice(0, 140),
      categoria: String(b.categoria || 'Geral').trim().slice(0, 40) || 'Geral',
      conteudo: conteudo.slice(0, 20000),
      criadoPor: eu.login,
      criadoPorNome: eu.nome,
      criadoEm: agora(),
      atualizadoEm: agora(),
    };
    db.estudos.unshift(estudo);
    if (db.estudos.length > 500) db.estudos.length = 500;
    saveDB();
    log(eu.login, 'ESTUDO_LANCADO', estudo.titulo);
    db.users.filter((u) => u.ativo).forEach((u) => {
      if (u.id !== eu.id) notificar(u.id, 'Novo estudo disponível', estudo.titulo + ' — veja em Estudos.');
    });
    return json(res, 200, { estudo });
  }

  const mEst = seg.match(/^estudos\/([a-f0-9]+)(?:\/(.+))?$/);
  if (mEst) {
    const estudo = db.estudos.find((e) => e.id === mEst[1]);
    if (!estudo) return json(res, 404, { error: 'Estudo não encontrado.' });
    const acao = mEst[2] || '';

    if (acao === 'estudar' && metodo === 'POST') {
      const jaEstudou = db.estudosLidos.find((x) => x.estudoId === estudo.id && x.userId === eu.id);
      if (jaEstudou) {
        db.estudosLidos = db.estudosLidos.filter((x) => !(x.estudoId === estudo.id && x.userId === eu.id));
        saveDB();
        return json(res, 200, { estudado: false });
      }
      db.estudosLidos.unshift({ id: uid(), estudoId: estudo.id, userId: eu.id, login: eu.login, nome: eu.nome, em: agora() });
      if (db.estudosLidos.length > 20000) db.estudosLidos.length = 20000;
      saveDB();
      log(eu.login, 'ESTUDO_CONCLUIDO', estudo.titulo);
      return json(res, 200, { estudado: true });
    }

    if (!acao && metodo === 'PUT') {
      if (!pode(eu, 'estudos')) return json(res, 403, { error: 'Seu cargo não edita estudos.' });
      const b = await lerCorpo(req);
      if (typeof b.titulo === 'string' && b.titulo.trim()) estudo.titulo = b.titulo.trim().slice(0, 140);
      if (typeof b.categoria === 'string' && b.categoria.trim()) estudo.categoria = b.categoria.trim().slice(0, 40);
      if (typeof b.conteudo === 'string' && b.conteudo.trim()) estudo.conteudo = b.conteudo.slice(0, 20000);
      estudo.atualizadoEm = agora();
      saveDB();
      log(eu.login, 'ESTUDO_EDITADO', estudo.titulo);
      return json(res, 200, { estudo });
    }

    if (!acao && metodo === 'DELETE') {
      if (!pode(eu, 'estudos')) return json(res, 403, { error: 'Seu cargo não exclui estudos.' });
      db.estudos = db.estudos.filter((e) => e.id !== estudo.id);
      db.estudosLidos = db.estudosLidos.filter((x) => x.estudoId !== estudo.id);
      saveDB();
      log(eu.login, 'ESTUDO_EXCLUIDO', estudo.titulo);
      return json(res, 200, { ok: true });
    }
  }

  // ---- regras do RP ----
  if (seg === 'regras' && metodo === 'PUT') {
    if (!pode(eu, 'regras')) return json(res, 403, { error: 'Seu cargo não edita as regras.' });
    const b = await lerCorpo(req);
    db.config.regras = String(b.texto || '').slice(0, 20000);
    saveDB();
    log(eu.login, 'REGRAS_ATUALIZADAS', 'regras do RP atualizadas');
    return json(res, 200, { regras: db.config.regras });
  }

  // ---- chat ----
  if (seg === 'chat' && metodo === 'POST') {
    const b = await lerCorpo(req);
    const lideres = String(b.canal || '') === 'lideres';
    if (lideres && !pode(eu, 'chatLideres')) {
      return json(res, 403, { error: 'Só quem tem a permissão do chat dos líderes pode escrever aqui.' });
    }
    const texto = String(b.texto || '').trim().slice(0, 800);
    if (!texto) return json(res, 400, { error: 'Mensagem vazia.' });
    const msg = { id: uid(), de: eu.login, nome: eu.nome, cargo: eu.cargo, texto, em: agora() };
    if (lideres) {
      db.chatLideres.push(msg);
      if (db.chatLideres.length > 1000) db.chatLideres = db.chatLideres.slice(-1000);
      // avisa os outros líderes que tem recado novo no canal fechado
      db.users.filter((u) => u.ativo && u.id !== eu.id && pode(u, 'chatLideres')).forEach((u) => {
        notificar(u.id, 'Chat dos líderes', `${eu.nome}: ${texto.slice(0, 120)}`);
      });
    } else {
      db.chat.push(msg);
      if (db.chat.length > 1000) db.chat = db.chat.slice(-1000);
    }
    saveDB();
    return json(res, 200, { mensagem: msg });
  }

  // ---- pedidos: folga, afastamento e justificativa de falta ----
  if (seg === 'solicitacoes' && metodo === 'POST') {
    if (!pode(eu, 'solicitacoesEnviar')) return json(res, 403, { error: 'Seu cargo não envia pedidos.' });
    const b = await lerCorpo(req);
    const tipo = String(b.tipo || '');
    if (!ROTULO_SOLICITACAO[tipo]) return json(res, 400, { error: 'Tipo de pedido inválido.' });
    const motivo = String(b.motivo || '').trim().slice(0, 400);
    if (motivo.length < 3) return json(res, 400, { error: 'Escreva o motivo do pedido.' });
    const dia = (v) => (/^\d{4}-\d{2}-\d{2}$/.test(String(v || '')) ? String(v) : null);
    const de = dia(b.de) || agora().slice(0, 10);
    let ate = dia(b.ate) || de;
    if (tipo !== 'afastamento') ate = de;
    if (ate < de) return json(res, 400, { error: 'A data final não pode ser antes da inicial.' });
    const sol = {
      id: uid(), userId: eu.id, login: eu.login, nome: eu.nome, cargo: eu.cargo,
      tipo, de, ate, motivo, status: 'pendente', criadoEm: agora(),
      respondidoPor: null, respondidoEm: null, resposta: '',
    };
    db.solicitacoes.unshift(sol);
    if (db.solicitacoes.length > 800) db.solicitacoes.length = 800;
    db.users.filter((u) => u.ativo && u.id !== eu.id && pode(u, 'solicitacoesResponder')).forEach((u) => {
      notificar(u.id, 'Novo pedido do efetivo', `${eu.nome} (${eu.cargo}): ${ROTULO_SOLICITACAO[tipo]} — ${motivo.slice(0, 110)}`);
      enviarPush([u.id], 'Novo pedido do efetivo', `${eu.nome}: ${ROTULO_SOLICITACAO[tipo]}`);
    });
    log(eu.login, 'PEDIDO_ENVIADO', `${ROTULO_SOLICITACAO[tipo]} ${de}${ate !== de ? ' a ' + ate : ''}`);
    saveDB();
    return json(res, 200, { solicitacao: sol });
  }

  if (seg === 'solicitacoes/responder' && metodo === 'POST') {
    if (!pode(eu, 'solicitacoesResponder')) return json(res, 403, { error: 'Seu cargo não responde pedidos.' });
    const b = await lerCorpo(req);
    const sol = db.solicitacoes.find((x) => x.id === b.id);
    if (!sol) return json(res, 404, { error: 'Pedido não encontrado.' });
    const status = b.status === 'aprovada' ? 'aprovada' : (b.status === 'recusada' ? 'recusada' : null);
    if (!status) return json(res, 400, { error: 'Resposta inválida.' });
    sol.status = status;
    sol.resposta = String(b.resposta || '').trim().slice(0, 300);
    sol.respondidoPor = eu.nome;
    sol.respondidoEm = agora();
    const tituloAviso = status === 'aprovada' ? 'Pedido aprovado' : 'Pedido recusado';
    const textoAviso = `${ROTULO_SOLICITACAO[sol.tipo]} (${sol.de}${sol.ate !== sol.de ? ' a ' + sol.ate : ''}): ${sol.resposta || (status === 'aprovada' ? 'aprovado pela liderança.' : 'recusado pela liderança.')}`;
    notificar(sol.userId, tituloAviso, textoAviso);
    enviarPush([sol.userId], `${tituloAviso} — ${eu.nome}`, textoAviso);
    log(eu.login, status === 'aprovada' ? 'PEDIDO_APROVADO' : 'PEDIDO_RECUSADO', `${sol.login}: ${ROTULO_SOLICITACAO[sol.tipo]} ${sol.de}`);
    saveDB();
    return json(res, 200, { solicitacao: sol });
  }

  if (seg === 'solicitacoes/remover' && metodo === 'POST') {
    const b = await lerCorpo(req);
    const sol = db.solicitacoes.find((x) => x.id === b.id);
    if (!sol) return json(res, 404, { error: 'Pedido não encontrado.' });
    const dono = sol.userId === eu.id && sol.status === 'pendente';
    if (!dono && !pode(eu, 'solicitacoesResponder')) return json(res, 403, { error: 'Sem permissão para apagar este pedido.' });
    db.solicitacoes = db.solicitacoes.filter((x) => x.id !== sol.id);
    saveDB();
    log(eu.login, 'PEDIDO_APAGADO', `${sol.login}: ${ROTULO_SOLICITACAO[sol.tipo]}`);
    return json(res, 200, { ok: true });
  }

  // ---- tirar a folga / encerrar o afastamento (o comando libera na hora) ----
  if (seg === 'solicitacoes/tirar' && metodo === 'POST') {
    const b = await lerCorpo(req);
    const podeComando = pode(eu, 'solicitacoesResponder') || pode(eu, 'equipes');
    let sol = null;
    if (b.id) {
      sol = (db.solicitacoes || []).find((x) => x.id === b.id) || null;
    } else if (b.userId) {
      const hoje0 = hojeLocalISO();
      sol = (db.solicitacoes || []).filter((x) => x.userId === b.userId && x.status === 'aprovada'
        && (x.tipo === 'folga' || x.tipo === 'afastamento'))
        .sort((x, y) => String(y.de).localeCompare(String(x.de)))
        .find((x) => x.tipo === 'folga' ? x.de === hoje0 : (x.de <= hoje0 && (x.ate || x.de) >= hoje0)) || null;
      if (!sol) {
        sol = (db.solicitacoes || []).find((x) => x.userId === b.userId && x.status === 'aprovada'
          && (x.tipo === 'folga' || x.tipo === 'afastamento')) || null;
      }
    }
    if (!sol) return json(res, 404, { error: 'Não achei folga nem afastamento aprovado para tirar.' });
    if (!podeComando && sol.userId !== eu.id) return json(res, 403, { error: 'Só o comando tira a folga de outra pessoa.' });
    if (sol.status !== 'aprovada') return json(res, 400, { error: 'Este pedido não está aprovado (já foi encerrado ou recusado).' });
    const rotulo = sol.tipo === 'afastamento' ? 'afastamento' : 'folga';
    sol.status = 'cancelada';
    sol.encerradaPor = eu.nome;
    sol.encerradaPorLogin = eu.login;
    sol.encerradaEm = agora();
    sol.resposta = String(b.resposta || '').trim().slice(0, 300)
      || (sol.userId === eu.id ? `${eu.nome} voltou ao serviço e retirou a própria ${rotulo}.` : `${rotulo.charAt(0).toUpperCase() + rotulo.slice(1)} retirada por ${eu.nome}.`);
    const aviso = sol.userId === eu.id
      ? `Você retirou a sua ${rotulo}. Já pode bater o ponto e entrar em serviço.`
      : `Sua ${rotulo} (${sol.tipo === 'afastamento' ? sol.de + (sol.ate && sol.ate !== sol.de ? ' a ' + sol.ate : '') : sol.de}) foi retirada por ${eu.nome}. Já pode bater o ponto e entrar em serviço.`;
    notificar(sol.userId, `🚔 ${rotulo.charAt(0).toUpperCase() + rotulo.slice(1)} retirada`, aviso);
    enviarPush([sol.userId], `${rotulo.charAt(0).toUpperCase() + rotulo.slice(1)} retirada`, aviso);
    log(eu.login, 'FOLGA_RETIRADA', `${sol.login}: ${rotulo} ${sol.de}`);
    saveDB();
    return json(res, 200, { solicitacao: sol, equipes: calcularEquipes() });
  }

  // ---- tickets: o comando cria as opções, o efetivo abre e o comando responde ----
  if (seg === 'tickets/opcoes' && metodo === 'POST') {
    if (!pode(eu, 'ticketsResponder')) return json(res, 403, { error: 'Seu cargo não cria opções de ticket.' });
    const b = await lerCorpo(req);
    const nome = String(b.nome || '').trim().slice(0, 60);
    if (nome.length < 2) return json(res, 400, { error: 'Escreva o nome da opção de ticket.' });
    const descricao = String(b.descricao || '').trim().slice(0, 200);
    const igual = db.ticketOpcoes.find((o) => String(o.nome).toLowerCase() === nome.toLowerCase());
    if (b.id) {
      const op = db.ticketOpcoes.find((o) => o.id === b.id);
      if (!op) return json(res, 404, { error: 'Opção de ticket não encontrada.' });
      if (igual && igual.id !== op.id) return json(res, 400, { error: 'Já existe uma opção de ticket com esse nome.' });
      const antes = op.nome;
      op.nome = nome;
      op.descricao = descricao;
      op.editadoPor = eu.nome;
      op.editadoEm = agora();
      db.tickets.forEach((t) => { if (t.opcaoId === op.id) t.opcao = nome; });
      log(eu.login, 'TICKET_OPCAO_EDITADA', `${antes} -> ${nome}`);
      saveDB();
      return json(res, 200, { opcao: op, ticketOpcoes: db.ticketOpcoes });
    }
    if (igual) return json(res, 400, { error: 'Já existe uma opção de ticket com esse nome.' });
    if (db.ticketOpcoes.length >= 30) return json(res, 400, { error: 'Já tem 30 opções de ticket. Apague alguma antes de criar outra.' });
    const op = { id: uid(), nome, descricao, criadoPor: eu.nome, criadoEm: agora() };
    db.ticketOpcoes.push(op);
    log(eu.login, 'TICKET_OPCAO_CRIADA', nome);
    saveDB();
    return json(res, 200, { opcao: op, ticketOpcoes: db.ticketOpcoes });
  }

  if (seg === 'tickets/opcoes/remover' && metodo === 'POST') {
    if (!pode(eu, 'ticketsResponder')) return json(res, 403, { error: 'Sem permissão para apagar opções de ticket.' });
    const b = await lerCorpo(req);
    const op = db.ticketOpcoes.find((o) => o.id === b.id);
    if (!op) return json(res, 404, { error: 'Opção de ticket não encontrada.' });
    db.ticketOpcoes = db.ticketOpcoes.filter((o) => o.id !== op.id);
    db.config.ticketOpcoesEditado = true;
    log(eu.login, 'TICKET_OPCAO_APAGADA', op.nome);
    saveDB();
    return json(res, 200, { ok: true, ticketOpcoes: db.ticketOpcoes });
  }

  if (seg === 'tickets' && metodo === 'POST') {
    if (!pode(eu, 'ticketsAbrir')) return json(res, 403, { error: 'Seu cargo não abre tickets.' });
    const b = await lerCorpo(req);
    const opcao = db.ticketOpcoes.find((o) => o.id === b.opcaoId) || null;
    if (!opcao) return json(res, 400, { error: 'Escolha a opção do ticket.' });
    const assunto = String(b.assunto || '').trim().slice(0, 120);
    if (assunto.length < 3) return json(res, 400, { error: 'Escreva o assunto do ticket.' });
    const mensagem = String(b.mensagem || '').trim().slice(0, 2000);
    if (mensagem.length < 5) return json(res, 400, { error: 'Escreva a sua mensagem no ticket.' });
    const abertosMeus = db.tickets.filter((t) => t.userId === eu.id && t.status !== 'fechado').length;
    if (abertosMeus >= 10) return json(res, 400, { error: 'Você já tem 10 tickets em aberto. Aguarde a resposta do comando.' });
    const tk = {
      id: uid(), userId: eu.id, login: eu.login, nome: eu.nome, cargo: eu.cargo,
      opcaoId: opcao.id, opcao: opcao.nome, assunto, mensagem,
      status: 'aberto', criadoEm: agora(), atualizadoEm: agora(), respostas: [],
      fechadoPor: null, fechadoEm: null,
    };
    db.tickets.unshift(tk);
    if (db.tickets.length > 1000) db.tickets.length = 1000;
    db.users.filter((u) => u.ativo && u.id !== eu.id && pode(u, 'ticketsResponder')).forEach((u) => {
      notificar(u.id, '🎫 Novo ticket do efetivo', `${eu.nome} (${eu.cargo}) · ${opcao.nome}: ${assunto}`);
      enviarPush([u.id], '🎫 Novo ticket no sistema', `${eu.nome}: ${opcao.nome} — ${assunto}`);
    });
    log(eu.login, 'TICKET_ABERTO', `${opcao.nome}: ${assunto}`);
    saveDB();
    return json(res, 200, { ticket: tk });
  }

  if (seg === 'tickets/responder' && metodo === 'POST') {
    if (!pode(eu, 'ticketsResponder')) return json(res, 403, { error: 'Seu cargo não responde tickets.' });
    const b = await lerCorpo(req);
    const tk = db.tickets.find((x) => x.id === b.id);
    if (!tk) return json(res, 404, { error: 'Ticket não encontrado.' });
    const texto = String(b.mensagem || '').trim().slice(0, 2000);
    if (texto.length < 2) return json(res, 400, { error: 'Escreva a resposta do ticket.' });
    if (!Array.isArray(tk.respostas)) tk.respostas = [];
    tk.respostas.push({ id: uid(), userId: eu.id, por: eu.nome, cargo: eu.cargo, login: eu.login, texto, em: agora() });
    if (tk.respostas.length > 60) tk.respostas = tk.respostas.slice(-60);
    if (tk.status !== 'fechado') tk.status = 'respondido';
    tk.atualizadoEm = agora();
    const aviso = `${tk.opcao} · ${tk.assunto}: ${texto.slice(0, 140)}`;
    notificar(tk.userId, '🎫 Seu ticket foi respondido', aviso);
    enviarPush([tk.userId], `🎫 Ticket respondido — ${eu.nome}`, aviso);
    log(eu.login, 'TICKET_RESPONDIDO', `${tk.login}: ${tk.assunto}`);
    saveDB();
    return json(res, 200, { ticket: tk });
  }

  if (seg === 'tickets/fechar' && metodo === 'POST') {
    const b = await lerCorpo(req);
    const tk = db.tickets.find((x) => x.id === b.id);
    if (!tk) return json(res, 404, { error: 'Ticket não encontrado.' });
    const dono = tk.userId === eu.id;
    if (!dono && !pode(eu, 'ticketsResponder')) return json(res, 403, { error: 'Sem permissão para fechar este ticket.' });
    if (tk.status === 'fechado') return json(res, 200, { ticket: tk });
    tk.status = 'fechado';
    tk.fechadoPor = eu.nome;
    tk.fechadoEm = agora();
    tk.atualizadoEm = agora();
    if (!dono) {
      const aviso = `Seu ticket (${tk.opcao} · ${tk.assunto}) foi encerrado por ${eu.nome}.`;
      notificar(tk.userId, '🎫 Ticket encerrado', aviso);
      enviarPush([tk.userId], '🎫 Ticket encerrado', aviso);
    }
    log(eu.login, 'TICKET_FECHADO', `${tk.login}: ${tk.assunto}`);
    saveDB();
    return json(res, 200, { ticket: tk });
  }

  if (seg === 'tickets/reabrir' && metodo === 'POST') {
    if (!pode(eu, 'ticketsResponder')) return json(res, 403, { error: 'Sem permissão para reabrir tickets.' });
    const b = await lerCorpo(req);
    const tk = db.tickets.find((x) => x.id === b.id);
    if (!tk) return json(res, 404, { error: 'Ticket não encontrado.' });
    tk.status = (Array.isArray(tk.respostas) && tk.respostas.length) ? 'respondido' : 'aberto';
    tk.fechadoPor = null;
    tk.fechadoEm = null;
    tk.atualizadoEm = agora();
    log(eu.login, 'TICKET_REABERTO', `${tk.login}: ${tk.assunto}`);
    saveDB();
    return json(res, 200, { ticket: tk });
  }

  // ---- advertências ----
  if (seg === 'advertencias' && metodo === 'POST') {
    if (!pode(eu, 'advertencias')) return json(res, 403, { error: 'Seu cargo não aplica advertências.' });
    const b = await lerCorpo(req);
    const alvo = db.users.find((u) => u.id === b.userId);
    if (!alvo) return json(res, 404, { error: 'Membro não encontrado.' });
    if (!ehMaster(eu) && nivel(alvo.cargo) >= nivel(eu.cargo)) {
      return json(res, 403, { error: 'Só é possível advertir quem está abaixo de você na hierarquia.' });
    }
    const motivo = String(b.motivo || '').trim().slice(0, 400);
    if (motivo.length < 3) return json(res, 400, { error: 'Escreva o motivo da advertência.' });
    const gravidade = ['leve', 'media', 'grave'].includes(String(b.gravidade)) ? String(b.gravidade) : 'leve';
    const adv = {
      id: uid(), userId: alvo.id, login: alvo.login, nome: alvo.nome, cargo: alvo.cargo,
      motivo, gravidade, aplicadaPor: eu.nome, aplicadaPorLogin: eu.login, em: agora(),
    };
    db.advertencias.unshift(adv);
    if (db.advertencias.length > 1000) db.advertencias.length = 1000;
    notificar(alvo.id, 'Advertência aplicada', `${eu.nome} aplicou uma advertência ${gravidade}: ${motivo.slice(0, 140)}`);
    enviarPush([alvo.id], 'Advertência aplicada', `${eu.nome}: ${motivo.slice(0, 120)}`);
    log(eu.login, 'ADVERTENCIA', `${alvo.login} (${gravidade}): ${motivo}`);
    saveDB();
    avisarAdvertenciaNoDiscord(adv);
    return json(res, 200, { advertencia: adv });
  }

  if (seg === 'advertencias/remover' && metodo === 'POST') {
    if (!pode(eu, 'advertencias')) return json(res, 403, { error: 'Sem permissão para tirar advertências.' });
    const b = await lerCorpo(req);
    const adv = db.advertencias.find((x) => x.id === b.id);
    if (!adv) return json(res, 404, { error: 'Advertência não encontrada.' });
    const justificativa = String(b.justificativa || '').trim().slice(0, 400);
    if (justificativa.length < 5) {
      return json(res, 400, { error: 'Escreva a justificativa: por que esta advertência está sendo tirada?' });
    }
    db.advertencias = db.advertencias.filter((x) => x.id !== adv.id);
    // guarda a advertência tirada com a justificativa (nada se perde do histórico)
    if (!Array.isArray(db.advertenciasRemovidas)) db.advertenciasRemovidas = [];
    db.advertenciasRemovidas.unshift({
      ...adv, removidaPor: eu.nome, removidaPorLogin: eu.login,
      removidaEm: agora(), justificativa,
    });
    if (db.advertenciasRemovidas.length > 500) db.advertenciasRemovidas.length = 500;
    saveDB();
    log(eu.login, 'ADVERTENCIA_TIRADA', `${adv.login} (${adv.gravidade}): ${adv.motivo.slice(0, 80)} | justificativa: ${justificativa.slice(0, 120)}`);
    notificar(adv.userId, 'Advertência retirada', `${eu.nome} tirou a advertência "${adv.motivo.slice(0, 100)}". Justificativa: ${justificativa.slice(0, 100)}`);
    avisarAdvertenciaNoDiscord(adv, {
      removida: true, removidaPor: eu.nome, removidaPorLogin: eu.login, justificativa, removidaEm: agora(),
    });
    return json(res, 200, { ok: true, justificativa });
  }

  // ---- cursos na ficha ----
  if (seg === 'cursos' && metodo === 'POST') {
    if (!pode(eu, 'cursos')) return json(res, 403, { error: 'Seu cargo não lança cursos na ficha.' });
    const b = await lerCorpo(req);
    const alvo = db.users.find((u) => u.id === b.userId);
    if (!alvo) return json(res, 404, { error: 'Membro não encontrado.' });
    const nome = String(b.nome || '').trim().slice(0, 80);
    if (nome.length < 3) return json(res, 400, { error: 'Escreva o nome do curso.' });
    const situacao = ['concluido', 'andamento'].includes(String(b.situacao)) ? String(b.situacao) : 'concluido';
    const curso = {
      id: uid(), userId: alvo.id, login: alvo.login, nome: alvo.nome, cargo: alvo.cargo,
      cursoNome: nome, carga: String(b.carga || '').trim().slice(0, 20),
      situacao, lancadoPor: eu.nome, em: agora(),
    };
    db.cursos.unshift(curso);
    if (db.cursos.length > 1000) db.cursos.length = 1000;
    notificar(alvo.id, 'Curso na sua ficha', `${eu.nome} lançou o curso "${nome}" (${situacao === 'concluido' ? 'concluído' : 'em andamento'}).`);
    enviarPush([alvo.id], 'Curso lançado na sua ficha', nome);
    log(eu.login, 'CURSO_LANCADO', `${alvo.login}: ${nome}`);
    saveDB();
    return json(res, 200, { curso });
  }

  if (seg === 'cursos/remover' && metodo === 'POST') {
    if (!pode(eu, 'cursos')) return json(res, 403, { error: 'Sem permissão para apagar cursos.' });
    const b = await lerCorpo(req);
    const curso = db.cursos.find((x) => x.id === b.id);
    if (!curso) return json(res, 404, { error: 'Curso não encontrado.' });
    db.cursos = db.cursos.filter((x) => x.id !== curso.id);
    saveDB();
    log(eu.login, 'CURSO_APAGADO', `${curso.login}: ${curso.cursoNome}`);
    return json(res, 200, { ok: true });
  }

  // ---- turnos ----
  if (seg === 'turnos' && metodo === 'POST') {
    if (!pode(eu, 'turnos')) return json(res, 403, { error: 'Seu cargo não cria turnos.' });
    const b = await lerCorpo(req);
    const nome = String(b.nome || '').trim().slice(0, 60);
    if (nome.length < 2) return json(res, 400, { error: 'Escreva o nome do turno.' });
    const data = /^\d{4}-\d{2}-\d{2}$/.test(String(b.data || '')) ? String(b.data) : agora().slice(0, 10);
    const hora = /^([01]\d|2[0-3]):[0-5]\d$/.test(String(b.hora || '')) ? String(b.hora) : null;
    if (!hora) return json(res, 400, { error: 'Escolha a hora do turno.' });
    const membros = (Array.isArray(b.membros) ? b.membros : []).filter((id) => db.users.some((u) => u.id === id));
    if (!membros.length) return json(res, 400, { error: 'Escolha pelo menos um policial para o turno.' });
    // o mesmo policial não fica em dois turnos no mesmo dia e hora
    const choque = db.turnos.find((t) => t.data === data && t.hora === hora && Array.isArray(t.membros) && t.membros.some((id) => membros.includes(id)));
    if (choque) return json(res, 400, { error: `Já existe o turno "${choque.nome}" nesse mesmo horário com alguém dessa lista.` });
    const turno = {
      id: uid(), nome, data, hora, membros, obs: String(b.obs || '').trim().slice(0, 200),
      criadoPor: eu.login, criadoPorNome: eu.nome, criadoEm: agora(), avisos: {},
    };
    db.turnos.push(turno);
    if (db.turnos.length > 500) db.turnos = db.turnos.slice(-500);
    const quando = `${data.split('-').reverse().join('/')} às ${hora}`;
    membros.filter((id) => id !== eu.id).forEach((id) => {
      notificar(id, 'Você foi escalado num turno', `${nome} — ${quando}.`);
      enviarPush([id], 'Novo turno para você', `${nome} — ${quando}.`);
    });
    log(eu.login, 'TURNO_CRIADO', `${nome} — ${quando} (${membros.length} policiais)`);
    saveDB();
    return json(res, 200, { turno });
  }

  if (seg === 'turnos/editar' && metodo === 'POST') {
    if (!pode(eu, 'turnos')) return json(res, 403, { error: 'Seu cargo não edita turnos.' });
    const b = await lerCorpo(req);
    const turno = db.turnos.find((x) => x.id === b.id);
    if (!turno) return json(res, 404, { error: 'Turno não encontrado.' });
    const nome = String(b.nome || '').trim().slice(0, 60);
    if (nome.length < 2) return json(res, 400, { error: 'Escreva o nome do turno.' });
    const data = /^\d{4}-\d{2}-\d{2}$/.test(String(b.data || '')) ? String(b.data) : turno.data;
    const hora = /^([01]\d|2[0-3]):[0-5]\d$/.test(String(b.hora || '')) ? String(b.hora) : null;
    if (!hora) return json(res, 400, { error: 'Escolha a hora do turno.' });
    const membros = (Array.isArray(b.membros) ? b.membros : []).filter((id) => db.users.some((u) => u.id === id));
    if (!membros.length) return json(res, 400, { error: 'Escolha pelo menos um policial para o turno.' });
    const choque = db.turnos.find((t) => t.id !== turno.id && t.data === data && t.hora === hora && Array.isArray(t.membros) && t.membros.some((id) => membros.includes(id)));
    if (choque) return json(res, 400, { error: `Já existe o turno "${choque.nome}" nesse mesmo horário com alguém dessa lista.` });
    const antes = Array.isArray(turno.membros) ? turno.membros.slice() : [];
    const mudouHorario = turno.data !== data || turno.hora !== hora;
    const saiu = antes.filter((id) => !membros.includes(id));
    const entrou = membros.filter((id) => !antes.includes(id));
    turno.nome = nome;
    turno.data = data;
    turno.hora = hora;
    turno.membros = membros;
    turno.obs = String(b.obs || '').trim().slice(0, 200);
    turno.editadoPor = eu.login;
    turno.editadoPorNome = eu.nome;
    turno.editadoEm = agora();
    if (mudouHorario) turno.avisos = {};
    const quando = `${data.split('-').reverse().join('/')} às ${hora}`;
    if (entrou.length) {
      entrou.filter((id) => id !== eu.id).forEach((id) => {
        notificar(id, 'Você foi escalado num turno', `${nome} — ${quando}.`);
        enviarPush([id], 'Novo turno para você', `${nome} — ${quando}.`);
      });
    } else if (mudouHorario) {
      membros.filter((id) => id !== eu.id).forEach((id) => {
        notificar(id, 'Seu turno mudou de horário', `${nome} — agora ${quando}.`);
        enviarPush([id], 'Seu turno mudou de horário', `${nome} — agora ${quando}.`);
      });
    }
    if (saiu.length) {
      saiu.forEach((id) => notificar(id, 'Você saiu de um turno', `${nome} — ${quando}.`));
    }
    log(eu.login, 'TURNO_EDITADO', `${nome} — ${quando} (${membros.length} policiais)`);
    saveDB();
    return json(res, 200, { turno });
  }

  if (seg === 'turnos/remover' && metodo === 'POST') {
    if (!pode(eu, 'turnos')) return json(res, 403, { error: 'Seu cargo não apaga turnos.' });
    const b = await lerCorpo(req);
    const turno = db.turnos.find((x) => x.id === b.id);
    if (!turno) return json(res, 404, { error: 'Turno não encontrado.' });
    db.turnos = db.turnos.filter((x) => x.id !== turno.id);
    saveDB();
    log(eu.login, 'TURNO_APAGADO', `${turno.nome} ${turno.data} ${turno.hora}`);
    return json(res, 200, { ok: true });
  }

  // ---- avisos no celular (push) ----
  if (seg === 'push/inscrever' && metodo === 'POST') {
    const b = await lerCorpo(req);
    const i = b.inscricao || b;
    if (!i || !i.endpoint) return json(res, 400, { error: 'Inscrição inválida.' });
    db.push = db.push.filter((x) => x.endpoint !== i.endpoint);
    db.push.push({ id: uid(), userId: eu.id, endpoint: String(i.endpoint).slice(0, 500), keys: i.keys || {}, em: agora() });
    if (db.push.length > 800) db.push = db.push.slice(-800);
    saveDB();
    return json(res, 200, { ok: true });
  }

  if (seg === 'push/teste' && metodo === 'POST') {
    enviarPush([eu.id], 'Aviso de teste', 'Se você está lendo isso no celular, os avisos estão funcionando.');
    return json(res, 200, { ok: true, aparelhos: db.push.filter((x) => x.userId === eu.id).length });
  }

  if (seg === 'push/sair' && metodo === 'POST') {
    const b = await lerCorpo(req);
    const ponta = String(b.endpoint || '').trim();
    db.push = db.push.filter((x) => (ponta ? x.endpoint !== ponta : x.userId !== eu.id));
    saveDB();
    return json(res, 200, { ok: true });
  }

  // ---- notificações ----
  if (seg === 'notificacoes/ler' && metodo === 'POST') {
    db.notificacoes.forEach((n) => { if (n.para === eu.id) n.lida = true; });
    saveDB();
    return json(res, 200, { ok: true });
  }

  // ---- configuração ----
  if (seg === 'config/icones' && metodo === 'POST') {
    if (!pode(eu, 'identidade')) return json(res, 403, { error: 'Seu cargo não troca a foto do sistema.' });
    const b = await lerCorpo(req);
    if (b.limpar) {
      db.config.icones = null;
      db.config.iconeV = Date.now();
      db.config.iconeLogoV = 0;
      saveDB();
      log(eu.login, 'ICONES_APP_LIMPOS', 'voltou para o brasão padrão no aplicativo');
      return json(res, 200, { config: configPublico() });
    }
    const partes = { i192: b.i192, i512: b.i512, mask: b.mask };
    for (const chave of Object.keys(partes)) {
      const valor = partes[chave];
      if (typeof valor !== 'string' || !/^data:image\/(png|jpeg|webp);base64,/.test(valor)) {
        return json(res, 400, { error: 'Ícone inválido.' });
      }
      if (valor.length > 2400000) return json(res, 400, { error: 'Ícone muito grande.' });
    }
    db.config.icones = { i192: partes.i192, i512: partes.i512, mask: partes.mask };
    db.config.iconeV = Date.now();
    db.config.iconeLogoV = Number(b.logoV || (db.config.logoV || 0)) || Date.now();
    saveDB();
    log(eu.login, 'ICONES_APP_ATUALIZADOS', 'ícone e nome do aplicativo atualizados com a foto do sistema');
    return json(res, 200, { config: configPublico() });
  }

  // ---- bot do Discord: aqui só se conecta o canal (o token fica no bot) ----
  if (seg === 'config/bot' && metodo === 'POST') {
    if (!ehMaster(eu) && !pode(eu, 'identidade')) return json(res, 403, { error: 'Só o Admin Master conecta o bot do Discord.' });
    const b = await lerCorpo(req);
    if (!db.config.discord || typeof db.config.discord !== 'object') db.config.discord = { webhook: '', ligado: true };
    if (!db.config.discord.bot || typeof db.config.discord.bot !== 'object') db.config.discord.bot = { canal: '', ligado: true };
    const bot = db.config.discord.bot;
    if (typeof b.canal === 'string') {
      const canal = b.canal.replace(/[^0-9]/g, '').slice(0, 32);
      if (b.canal.trim() && !/^[0-9]{15,25}$/.test(canal)) {
        return json(res, 400, { error: 'Esse não parece ser o ID do canal. São só números (ex.: 1234567890123456789).' });
      }
      bot.canal = canal;
      bot.ultimoErro = '';
    }
    if (typeof b.ligado === 'boolean') bot.ligado = b.ligado;
    if (b.canais && typeof b.canais === 'object') {
      if (!bot.canais || typeof bot.canais !== 'object') bot.canais = { promocao: '', rebaixamento: '' };
      for (const chave of ['promocao', 'rebaixamento']) {
        if (typeof b.canais[chave] !== 'string') continue;
        const id = b.canais[chave].replace(/[^0-9]/g, '').slice(0, 32);
        if (b.canais[chave].trim() && !/^[0-9]{15,25}$/.test(id)) {
          return json(res, 400, { error: 'O ID do canal de ' + nomeDoGrupo(chave) + ' não parece certo. São só números (ex.: 1234567890123456789).' });
        }
        bot.canais[chave] = id;
      }
    }
    saveDB();
    log(eu.login, 'BOT_CONFIG', bot.canal
      ? (bot.ligado ? 'canal do bot conectado (' + bot.canal + ')' : 'canal do bot salvo, avisos desligados')
      : 'canal do bot removido');
    let teste = null;
    if (b.teste) {
      const alvos = [
        { grupo: 'adv', canal: bot.canal },
        { grupo: 'promocao', canal: (bot.canais && bot.canais.promocao) || '' },
        { grupo: 'rebaixamento', canal: (bot.canais && bot.canais.rebaixamento) || '' },
      ].filter((x) => x.canal);
      if (!alvos.length) teste = { ok: false, erro: 'Cole primeiro o ID do canal do Discord.' };
      else if (!bot.ligado) teste = { ok: false, erro: 'Marque "Mandar os avisos por este bot" e salve antes de testar.' };
      else {
        alvos.forEach((x) => {
          enfileirarBot({
            allowed_mentions: { parse: [] },
            embeds: [{
              title: '✅ Teste — canal de ' + nomeDoGrupo(x.grupo),
              color: 0x2ecc71,
              description: 'Se você está lendo isso no canal de **' + nomeDoGrupo(x.grupo) + '**, é aqui que os avisos de ' + nomeDoGrupo(x.grupo) + ' do sistema vão aparecer.',
              footer: { text: 'Enviado por ' + textoAviso(eu.nome, 60) + ' · ' + agora() },
            }],
          }, 'teste_' + x.grupo, x.canal);
        });
        teste = {
          ok: true, naFila: true, canais: alvos.length,
          mensagem: (alvos.length > 1
            ? 'Teste na fila: ' + alvos.length + ' canais vão receber o cartão de teste em até 10 segundos.'
            : 'Teste na fila: o bot entrega no canal em até 10 segundos (se ele estiver online na Discloud).'),
        };
      }
    }
    return json(res, 200, { discord: estadoDiscord(), teste });
  }

  // ---- avisos no Discord (webhook do canal) ----
  if (seg === 'config/discord' && metodo === 'GET') {
    if (!ehMaster(eu) && !pode(eu, 'identidade')) return json(res, 403, { error: 'Só o Admin Master configura o Discord.' });
    return json(res, 200, { discord: estadoDiscord() });
  }

  if (seg === 'config/discord' && metodo === 'POST') {
    if (!ehMaster(eu) && !pode(eu, 'identidade')) return json(res, 403, { error: 'Só o Admin Master configura o Discord.' });
    const b = await lerCorpo(req);
    if (!db.config.discord || typeof db.config.discord !== 'object') db.config.discord = { webhook: '', ligado: true };
    if (typeof b.webhook === 'string') {
      const w = b.webhook.trim();
      if (w && !RE_WEBHOOK_DISCORD.test(w)) {
        return json(res, 400, { error: 'Esse não parece ser o link do webhook. Ele começa com https://discord.com/api/webhooks/ e vem com dois códigos compridos.' });
      }
      db.config.discord.webhook = w.slice(0, 300);
    }
    if (typeof b.ligado === 'boolean') db.config.discord.ligado = b.ligado;
    if (b.webhooks && typeof b.webhooks === 'object') {
      if (!db.config.discord.webhooks || typeof db.config.discord.webhooks !== 'object') {
        db.config.discord.webhooks = { promocao: '', rebaixamento: '' };
      }
      for (const chave of ['promocao', 'rebaixamento']) {
        if (typeof b.webhooks[chave] !== 'string') continue;
        const w = b.webhooks[chave].trim();
        if (w && !RE_WEBHOOK_DISCORD.test(w)) {
          return json(res, 400, { error: 'O webhook do canal de ' + nomeDoGrupo(chave) + ' não parece certo. Ele começa com https://discord.com/api/webhooks/ e vem com dois códigos compridos.' });
        }
        db.config.discord.webhooks[chave] = w.slice(0, 300);
      }
    }
    saveDB();
    log(eu.login, 'DISCORD_CONFIG', db.config.discord.webhook
      ? (db.config.discord.ligado ? 'canal do Discord ligado' : 'canal do Discord desligado')
      : 'canal do Discord removido');
    let teste = null;
    if (b.teste) {
      const c = discordDoConfig();
      if (!c.webhook) {
        teste = { ok: false, erro: 'Cole primeiro o link do webhook do canal.' };
      } else if (!c.ligado) {
        teste = { ok: false, erro: 'Marque "Mandar avisos para este canal" e salve antes de testar.' };
      } else {
        teste = await enviarDiscord({
          username: textoAviso((db.config && db.config.nomeSistema) || 'POLÍCIA FEDERAL', 60),
          allowed_mentions: { parse: [] },
          embeds: [{
            title: '✅ Teste do sistema',
            color: 0x2ecc71,
            description: 'Se você está lendo isso no canal, os avisos de advertência estão ligados. A partir de agora, cada advertência aplicada aparece aqui com o motivo, quem tomou e quantas a pessoa tem.',
            footer: { text: 'Enviado por ' + textoAviso(eu.nome, 60) + ' · ' + agora() },
          }],
        }, 'teste');
      }
    }
    return json(res, 200, { discord: estadoDiscord(), teste });
  }

  if (seg === 'config' && metodo === 'PUT') {
    if (!pode(eu, 'identidade')) return json(res, 403, { error: 'Seu cargo não troca a identidade do sistema.' });
    const b = await lerCorpo(req);
    if (typeof b.nomeSistema === 'string' && b.nomeSistema.trim()) db.config.nomeSistema = b.nomeSistema.trim().slice(0, 24);
    if (typeof b.nomeCorporacao === 'string') db.config.nomeCorporacao = b.nomeCorporacao.trim().slice(0, 80);
    if (typeof b.logo === 'string') {
      if (b.logo === '') { db.config.logo = null; db.config.logoSemFoto = true; }
      else if (b.logo.length > 8000000) return json(res, 400, { error: 'Foto muito grande. Use uma imagem menor.' });
      else if (!/^data:image\//.test(b.logo)) return json(res, 400, { error: 'Arquivo de imagem inválido.' });
      else { db.config.logo = b.logo; db.config.logoSemFoto = false; }
      db.config.logoV = Date.now();
    }
    if (typeof b.tema === 'string' && ['dourado', 'esmeralda', 'roxo', 'vermelho', 'azul'].includes(b.tema)) db.config.tema = b.tema;
    saveDB();
    log(eu.login, 'CONFIG_ALTERADA', `${db.config.nomeSistema} | ${db.config.nomeCorporacao}`);
    return json(res, 200, { config: configPublico() });
  }

  // ---- códigos Q (Admin Master e Chefe de Polícia editam) ----
  if (seg === 'codigosq' && metodo === 'PUT') {
    if (!pode(eu, 'codigosQ')) return json(res, 403, { error: 'Seu cargo não edita os Códigos Q.' });
    const b = await lerCorpo(req);
    if (!Array.isArray(b.codigos)) return json(res, 400, { error: 'Lista de códigos inválida.' });
    if (b.codigos.length > 300) return json(res, 400, { error: 'Muitos códigos (máx 300).' });
    const limpos = [];
    for (const item of b.codigos) {
      const codigo = String((item && item.codigo) || '').trim().toUpperCase().replace(/[^A-Z0-9\-]/g, '').slice(0, 10);
      const significado = String((item && item.significado) || '').trim().slice(0, 240);
      if (!codigo || !significado) continue;
      const grupo = String((item && item.grupo) || 'Outros').trim().slice(0, 40) || 'Outros';
      limpos.push({ codigo, significado, grupo });
    }
    db.config.codigosQ = limpos;
    db.config.codigosQEditado = true;
    saveDBNow();
    log(eu.login, 'CODIGOS_Q_ALTERADOS', `${limpos.length} códigos salvos`);
    return json(res, 200, { codigosQ: limpos });
  }

  if ((seg === 'codigosq/padrao' || seg === 'codigosq-padrao') && metodo === 'POST') {
    if (!pode(eu, 'codigosQ')) return json(res, 403, { error: 'Seu cargo não restaura os Códigos Q.' });
    db.config.codigosQ = CODIGOS_Q_PADRAO.map((c) => ({ ...c }));
    db.config.codigosQEditado = false;
    saveDBNow();
    log(eu.login, 'CODIGOS_Q_PADRAO', 'lista padrão restaurada');
    return json(res, 200, { codigosQ: db.config.codigosQ });
  }

  // ---- limpeza de dados (só Admin Master) ----
  if (seg === 'limpar' && metodo === 'POST') {
    if (!pode(eu, 'limpar')) return json(res, 403, { error: 'Seu cargo não pode limpar dados.' });
    const b = await lerCorpo(req);
    const alvo = String(b.alvo || '').toLowerCase();
    const alvos = ['chat', 'auditoria', 'ponto', 'pontuacao', 'ocorrencias', 'provas', 'tudo'];
    if (!alvos.includes(alvo)) return json(res, 400, { error: 'Alvo de limpeza inválido.' });

    const apagados = {};
    const limparChat = () => { apagados.mensagens = db.chat.length + db.chatLideres.length; db.chat = []; db.chatLideres = []; };
    const limparAuditoria = () => { apagados.auditoria = db.audit.length; db.audit = []; };
    const limparPonto = () => { apagados.pontosBatidos = db.ponto.length; db.ponto = []; };
    const limparPontuacao = () => { apagados.lancamentos = db.pontos.length; db.pontos = []; db.users.forEach((u) => { u.pontos = 0; }); };
    const limparOcorrencias = () => { apagados.ocorrencias = db.ocorrencias.length; db.ocorrencias = []; };
    const limparProvas = () => { apagados.provasEnviadas = db.entregas.length; db.entregas = []; };

    if (alvo === 'chat') limparChat();
    else if (alvo === 'auditoria') limparAuditoria();
    else if (alvo === 'ponto') limparPonto();
    else if (alvo === 'pontuacao') limparPontuacao();
    else if (alvo === 'ocorrencias') limparOcorrencias();
    else if (alvo === 'provas') limparProvas();
    else {
      // tudo: apaga os registros, mantendo contas, regras, estudos e a identidade
      limparChat(); limparAuditoria(); limparPonto(); limparPontuacao(); limparOcorrencias(); limparProvas();
      apagados.estudosLidos = db.estudosLidos.length;
      db.estudosLidos = [];
      apagados.notificacoes = db.notificacoes.length;
      db.notificacoes = [];
    }

    saveDBNow();
    const resumo = Object.entries(apagados).map(([k, v]) => `${v} ${k}`).join(', ') || 'nada';
    log(eu.login, 'DADOS_LIMPOS', `${alvo}: ${resumo}`);
    return json(res, 200, { ok: true, alvo, apagados, mensagem: 'Limpeza feita: ' + resumo + '.' });
  }

  // ---- cargos: criar, renomear, ordenar, excluir e permissões (só Admin Master) ----
  const limpaPermissoes = (entrada) => {
    const saida = {};
    const dado = (entrada && typeof entrada === 'object') ? entrada : {};
    PERMISSOES.forEach((p) => { saida[p.chave] = dado[p.chave] === true; });
    return saida;
  };

  if (seg === 'cargos' && metodo === 'POST') {
    if (!ehMaster(eu)) return json(res, 403, { error: 'Só o Admin Master cria cargos.' });
    const b = await lerCorpo(req);
    const nome = String(b.nome || '').trim().replace(/\s+/g, ' ').slice(0, 30);
    if (nome.length < 2) return json(res, 400, { error: 'Escreva o nome do cargo (mínimo 2 letras).' });
    if (listaCargos().some((c) => c.nome.toLowerCase() === nome.toLowerCase())) {
      return json(res, 400, { error: 'Já existe um cargo com esse nome.' });
    }
    if (db.config.cargos.length >= 20) return json(res, 400, { error: 'Limite de 20 cargos.' });
    db.config.cargos.push({ nome, nivel: 10, master: false, cor: limpaCorCargo(b.cor), permissoes: limpaPermissoes(b.permissoes) });
    normalizarCargos();
    saveDBNow();
    log(eu.login, 'CARGO_CRIADO', nome);
    return json(res, 200, { cargos: listaCargos() });
  }

  if (seg === 'cargos' && metodo === 'PUT') {
    if (!ehMaster(eu)) return json(res, 403, { error: 'Só o Admin Master troca o nome dos cargos.' });
    const b = await lerCorpo(req);
    const de = String(b.de || '').trim();
    const alvo = db.config.cargos.find((c) => c.nome === de);
    if (!alvo) return json(res, 404, { error: 'Cargo não encontrado.' });
    const para = String(b.para == null ? de : b.para).trim().replace(/\s+/g, ' ').slice(0, 30);
    if (para.length < 2) return json(res, 400, { error: 'Nome do cargo muito curto.' });
    if (para !== de && listaCargos().some((c) => c.nome.toLowerCase() === para.toLowerCase())) {
      return json(res, 400, { error: 'Já existe um cargo com esse nome.' });
    }
    if (para !== de) {
      alvo.nome = para;
      db.users.forEach((u) => { if (u.cargo === de) u.cargo = para; });
      db.ocorrencias.forEach((o) => { if (o.cargoAgente === de) o.cargoAgente = para; });
      db.chat.forEach((m) => { if (m.cargo === de) m.cargo = para; });
      db.chatLideres.forEach((m) => { if (m.cargo === de) m.cargo = para; });
      db.entregas.forEach((e) => { if (e.cargo === de) e.cargo = para; });
      log(eu.login, 'CARGO_RENOMEADO', `${de} -> ${para}`);
    }
    if (b.cor !== undefined) {
      alvo.cor = limpaCorCargo(b.cor);
      log(eu.login, 'CARGO_COR', `${para}: ${alvo.cor || 'padrão'}`);
    }
    if (b.permissoes && typeof b.permissoes === 'object') {
      alvo.permissoes = limpaPermissoes(b.permissoes);
      log(eu.login, 'CARGO_PERMISSOES', para);
    }
    normalizarCargos();
    saveDBNow();
    return json(res, 200, { cargos: listaCargos() });
  }

  if (seg === 'cargos/cor' && metodo === 'POST') {
    if (!ehMaster(eu)) return json(res, 403, { error: 'Só o Admin Master muda a cor dos cargos.' });
    const b = await lerCorpo(req);
    const nome = String(b.nome || '').trim();
    const alvo = db.config.cargos.find((c) => c.nome === nome);
    if (!alvo) return json(res, 404, { error: 'Cargo não encontrado.' });
    alvo.cor = limpaCorCargo(b.cor);
    normalizarCargos();
    saveDBNow();
    log(eu.login, 'CARGO_COR', `${nome}: ${alvo.cor || 'padrão'}`);
    return json(res, 200, { ok: true, cargos: listaCargos() });
  }

  if (seg === 'cargos/ordem' && metodo === 'POST') {
    if (!ehMaster(eu)) return json(res, 403, { error: 'Só o Admin Master muda a ordem dos cargos.' });
    const b = await lerCorpo(req);
    if (!Array.isArray(b.ordem)) return json(res, 400, { error: 'Ordem inválida.' });
    const atual = db.config.cargos.slice();
    const nova = [];
    b.ordem.forEach((nome) => {
      const achado = atual.find((c) => c.nome === String(nome || '').trim());
      if (achado && !nova.includes(achado)) nova.push(achado);
    });
    atual.forEach((c) => { if (!nova.includes(c)) nova.push(c); });
    db.config.cargos = nova;
    normalizarCargos();
    saveDBNow();
    log(eu.login, 'CARGOS_ORDENADOS', nova.map((c) => c.nome).join(' > '));
    return json(res, 200, { cargos: listaCargos() });
  }

  if (seg === 'cargos/remover' && metodo === 'POST') {
    if (!ehMaster(eu)) return json(res, 403, { error: 'Só o Admin Master exclui cargos.' });
    const b = await lerCorpo(req);
    const nome = String(b.nome || '').trim();
    const alvo = db.config.cargos.find((c) => c.nome === nome);
    if (!alvo) return json(res, 404, { error: 'Cargo não encontrado.' });
    if (alvo.master) return json(res, 400, { error: 'O cargo de dono do sistema não pode ser excluído.' });
    const quantos = db.users.filter((u) => u.cargo === nome).length;
    if (quantos) return json(res, 400, { error: `Tem ${quantos} pessoa(s) neste cargo. Mude o cargo delas antes de excluir.` });
    db.config.cargos = db.config.cargos.filter((c) => c.nome !== nome);
    normalizarCargos();
    saveDBNow();
    log(eu.login, 'CARGO_EXCLUIDO', nome);
    return json(res, 200, { cargos: listaCargos() });
  }

  // ---- backup ----
  if (seg === 'backup' && metodo === 'GET') {
    if (!pode(eu, 'backup')) return json(res, 403, { error: 'Seu cargo não baixa backup.' });
    log(eu.login, 'BACKUP_GERADO', 'download completo');
    saveDBNow();
    return json(res, 200, { geradoEm: agora(), por: eu.login, dados: db });
  }

  if (seg === 'restore' && metodo === 'POST') {
    if (!pode(eu, 'restaurar')) return json(res, 403, { error: 'Seu cargo não restaura backup.' });
    const b = await lerCorpo(req);
    const d = b.dados || b;
    if (!d || !Array.isArray(d.users)) return json(res, 400, { error: 'Arquivo de backup inválido.' });
    db = { ...DB_VAZIO, ...d };
    migrar();
    saveDBNow();
    log(eu.login, 'BACKUP_RESTAURADO', `${db.users.length} usuários, ${db.ocorrencias.length} ocorrências`);
    return json(res, 200, { ok: true });
  }

  return json(res, 404, { error: 'Rota não encontrada.' });
}

// ───────── arquivos estáticos ─────────
const MIME = {
  '.html': 'text/html; charset=utf-8', '.css': 'text/css; charset=utf-8',
  '.js': 'application/javascript; charset=utf-8', '.json': 'application/json; charset=utf-8',
  '.png': 'image/png', '.jpg': 'image/jpeg', '.jpeg': 'image/jpeg', '.svg': 'image/svg+xml',
  '.ico': 'image/x-icon', '.webp': 'image/webp',
};
const EMBUTIDOS = {"/index.html":"","/style.css":"","/app.js":"","/sw.js":"","/icon-192.png":"","/icon-512.png":"","/icon-maskable-512.png":""};
const EMBUTIDOS_BUF = {};
Object.keys(EMBUTIDOS).forEach((k) => { EMBUTIDOS_BUF[k] = Buffer.from(EMBUTIDOS[k], 'base64'); });

function serveEstatico(req, res, urlPath) {
  let rel = decodeURIComponent(urlPath.split('?')[0]);
  if (rel === '/') rel = '/index.html';
  if (EMBUTIDOS_BUF[rel]) {
    res.writeHead(200, { 'Content-Type': MIME[path.extname(rel)] || 'application/octet-stream', 'Content-Length': EMBUTIDOS_BUF[rel].length });
    return res.end(EMBUTIDOS_BUF[rel]);
  }
  const file = path.join(PUBLIC_DIR, path.normalize(rel).replace(/^(\.\.[/\\])+/, ''));
  if (!file.startsWith(PUBLIC_DIR)) { res.writeHead(403); return res.end('403'); }
  fs.readFile(file, (err, data) => {
    if (err) { res.writeHead(404, { 'Content-Type': 'text/plain' }); return res.end('Não encontrado'); }
    res.writeHead(200, { 'Content-Type': MIME[path.extname(file)] || 'application/octet-stream' });
    res.end(data);
  });
}

const server = http.createServer(async (req, res) => {
  const url = req.url || '/';
  if (req.method === 'OPTIONS') {
    res.writeHead(204, {
      'Access-Control-Allow-Origin': '*',
      'Access-Control-Allow-Methods': 'GET,POST,PUT,DELETE,OPTIONS',
      'Access-Control-Allow-Headers': 'Content-Type,Authorization',
    });
    return res.end();
  }
  const caminhoIcone = url.split('?')[0];
  if (caminhoIcone === '/icon-app-192.png' || caminhoIcone === '/icon-app-512.png' ||
      caminhoIcone === '/icon-app-maskable.png' || caminhoIcone === '/apple-touch-icon.png') {
    const guardados = (db.config && db.config.icones) || {};
    const chaveIcone = caminhoIcone === '/icon-app-192.png' || caminhoIcone === '/apple-touch-icon.png'
      ? 'i192'
      : caminhoIcone === '/icon-app-512.png' ? 'i512' : 'mask';
    const salvo = guardados[chaveIcone];
    if (salvo) {
      const mi = /^data:(image\/[a-z0-9.+-]+);base64,(.+)$/i.exec(salvo);
      if (mi) {
        const bufIcone = Buffer.from(mi[2], 'base64');
        res.writeHead(200, {
          'Content-Type': mi[1],
          'Content-Length': bufIcone.length,
          'Cache-Control': 'no-cache',
          'Access-Control-Allow-Origin': '*',
        });
        return res.end(bufIcone);
      }
    }
    // sem foto escolhida: manda o brasao padrao que ja vem dentro do sistema
    const padrao = caminhoIcone === '/icon-app-192.png' || caminhoIcone === '/apple-touch-icon.png'
      ? (EMBUTIDOS_BUF['/icon-192.png'] || null)
      : caminhoIcone === '/icon-app-512.png'
        ? (EMBUTIDOS_BUF['/icon-512.png'] || null)
        : (EMBUTIDOS_BUF['/icon-maskable-512.png'] || null);
    if (!padrao) { res.writeHead(404, { 'Content-Type': 'text/plain' }); return res.end('sem icone'); }
    res.writeHead(200, { 'Content-Type': 'image/png', 'Content-Length': padrao.length, 'Cache-Control': 'no-cache' });
    return res.end(padrao);
  }
  if (url.split('?')[0] === '/logo') {
    const emUso = logoEmUso();
    if (!emUso) { res.writeHead(404, { 'Content-Type': 'text/plain' }); return res.end('sem foto'); }
    const m = /^data:(image\/[a-z0-9.+-]+);base64,(.+)$/i.exec(emUso);
    if (!m) { res.writeHead(404, { 'Content-Type': 'text/plain' }); return res.end('sem foto'); }
    const buf = Buffer.from(m[2], 'base64');
    res.writeHead(200, { 'Content-Type': m[1], 'Content-Length': buf.length, 'Cache-Control': 'public, max-age=31536000, immutable' });
    return res.end(buf);
  }
  if (url.split('?')[0].startsWith('/foto/ocorrencia/')) {
    const id = url.split('?')[0].slice('/foto/ocorrencia/'.length).replace(/\/+$/, '');
    const oc = db.ocorrencias.find((o) => o.id === id);
    const m = oc && /^data:(image\/[a-z0-9.+-]+);base64,(.+)$/i.exec(oc.foto || '');
    if (!m) { res.writeHead(404, { 'Content-Type': 'text/plain; charset=utf-8' }); return res.end('sem foto'); }
    const buf = Buffer.from(m[2], 'base64');
    res.writeHead(200, {
      'Content-Type': m[1],
      'Content-Length': buf.length,
      'Cache-Control': 'public, max-age=86400',
      'Access-Control-Allow-Origin': '*',
    });
    return res.end(buf);
  }
  const caminho = url.split('?')[0];
  if (caminho === '/manifest.webmanifest' || caminho === '/manifest.json') {
    const cfg = (typeof db !== 'undefined' && db && db.config) || {};
    const nomeSis = String(cfg.nomeSistema || NOME_PADRAO);
    const corp = String(cfg.nomeCorporacao || CORP_PADRAO);
    const versaoIcone = Number(cfg.iconeV || cfg.logoV || 1) || 1;
    const manifest = {
      name: nomeSis + ' — Sistema Interno',
      short_name: String(nomeSis).slice(0, 24),
      description: corp + ' — sistema interno de gestão policial.',
      lang: 'pt-BR',
      dir: 'ltr',
      start_url: '/?app=1',
      scope: '/',
      display: 'standalone',
      display_override: ['standalone', 'minimal-ui'],
      orientation: 'portrait',
      background_color: '#090b0f',
      theme_color: '#090b0f',
      categories: ['productivity', 'utilities'],
      icons: [
        { src: '/icon-app-192.png?v=' + versaoIcone, sizes: '192x192', type: 'image/png', purpose: 'any' },
        { src: '/icon-app-512.png?v=' + versaoIcone, sizes: '512x512', type: 'image/png', purpose: 'any' },
        { src: '/icon-app-maskable.png?v=' + versaoIcone, sizes: '512x512', type: 'image/png', purpose: 'maskable' },
      ],
    };
    const bufManifest = Buffer.from(JSON.stringify(manifest), 'utf8');
    res.writeHead(200, {
      'Content-Type': 'application/manifest+json; charset=utf-8',
      'Content-Length': bufManifest.length,
      'Cache-Control': 'no-cache',
    });
    return res.end(bufManifest);
  }
  if (url.startsWith('/api')) {
    const seg = url.slice(5).split('?')[0].replace(/^\/+/, '');
    try {
      return await api(req, res, seg);
    } catch (e) {
      console.error('Erro na API:', e.message);
      return json(res, 500, { error: e.message || 'Erro interno.' });
    }
  }
  return serveEstatico(req, res, url);
});

// avisa 15 minutos antes e na hora de cada turno (uma vez por pessoa)
function inicioDoTurno(t) {
  const ms = Date.parse(`${t.data}T${t.hora}:00-04:00`);
  return Number.isNaN(ms) ? null : ms;
}

function checarTurnos() {
  if (!Array.isArray(db.turnos) || !db.turnos.length) return;
  const agoraMs = Date.now();
  let mudou = false;
  db.turnos.forEach((t) => {
    const ini = inicioDoTurno(t);
    if (ini === null) return;
    if (!t.avisos || typeof t.avisos !== 'object') t.avisos = {};
    const quando = `${String(t.data || '').split('-').reverse().join('/')} às ${t.hora}`;
    (Array.isArray(t.membros) ? t.membros : []).forEach((id) => {
      const u = db.users.find((x) => x.id === id);
      if (!u || !u.ativo) return;
      if (agoraMs >= ini - 15 * 60000 && agoraMs < ini && !t.avisos[id + ':15']) {
        t.avisos[id + ':15'] = agora();
        notificar(id, 'Turno em 15 minutos', `${t.nome} — ${quando}. Já vai se preparando.`);
        enviarPush([id], 'Turno em 15 minutos', `${t.nome} — ${quando}.`);
        mudou = true;
      }
      if (agoraMs >= ini && agoraMs <= ini + 2 * 3600000 && !t.avisos[id + ':0']) {
        t.avisos[id + ':0'] = agora();
        notificar(id, 'É hora do seu turno', `${t.nome} — ${quando}. Bom serviço!`);
        enviarPush([id], 'É hora do seu turno', `${t.nome} — ${quando}. Bom serviço!`);
        mudou = true;
      }
    });
  });
  if (mudou) saveDB();
}

async function iniciar() {
  const temBanco = abrirBanco();
  let carregou = false;
  if (temBanco) {
    try {
      carregou = await carregarDoBanco();
      if (carregou) console.log('Dados carregados do banco de dados (nada se perde ao reiniciar).');
      else console.log('Banco vazio: criando os dados iniciais.');
    } catch (e) {
      console.error('Não consegui acessar o banco (' + e.message + '). Usando data.json por enquanto.');
      pool = null;
    }
  } else {
    console.log('Sem DATABASE_URL: usando data.json (os dados somem quando o Render reinicia).');
  }
  if (!carregou) loadDB();
  migrar();
  seed();
  checarTurnos();
  setInterval(checarTurnos, 20000);
  setInterval(() => { enviarPendentesDiscord().catch(() => {}); }, 20000);   // avisos guardados do Discord
  varrerProvasEmAndamento();
  fecharPontosDaMeiaNoite();
  setInterval(varrerProvasEmAndamento, 15000);
  setInterval(fecharPontosDaMeiaNoite, 60000);

  server.listen(PORT, () => {
    console.log('\n  ' + NOME_PADRAO + ' rodando em http://localhost:' + PORT);
    if (pool) console.log('  Banco de dados: ligado (persistente).');
    console.log('  Login inicial: admin / admin123  (troque a senha depois)\n');
  });
}
iniciar();
